const S={finance:['OpenStax · Principles of Finance','https://openstax.org/details/books/principles-finance','重点读风险、收益、资本预算与融资，完成章后题。'],econ:['CORE · The Economy 2.0','https://books.core-econ.org/the-economy/index.html','从劳动、企业、市场失灵与不平等单元进入；用模型解释制度差异。'],economics:['OpenStax · Principles of Economics 3e','https://openstax.org/details/books/principles-economics-3e','阅读与本主题对应的微观及宏观章节，核对模型假设。'],management:['OpenStax · Principles of Management','https://openstax.org/details/books/principles-management','阅读组织、领导、战略与控制章节，对照案例练习。'],marketing:['OpenStax · Principles of Marketing','https://openstax.org/details/books/principles-marketing','阅读消费者行为、市场细分、产品和营销衡量章节。'],venture:['OpenStax · Entrepreneurship','https://openstax.org/details/books/entrepreneurship','重点读机会识别、商业模式、商业计划和融资，完成可行性检验。'],ethics:['OpenStax · Business Ethics','https://openstax.org/details/books/business-ethics','比较利益相关者、员工、消费者与环境责任的伦理论证。'],physics:['OpenStax · University Physics Volume 1','https://openstax.org/details/books/university-physics-volume-1','以向量、牛顿定律、功与能量、动量为主线，完成计算题。'],chemistry:['OpenStax · Chemistry 2e','https://openstax.org/details/books/chemistry-2e','阅读化学计量、热力学、平衡、电化学和动力学章节。'],biology:['OpenStax · Biology 2e','https://openstax.org/details/books/biology-2e','按细胞、遗传、进化、生态顺序阅读，核对机制和证据。'],calculus:['OpenStax · Calculus Volume 1','https://openstax.org/details/books/calculus-volume-1','掌握函数、极限、导数、积分及应用；每章完成证明和计算。'],statistics:['OpenStax · Introductory Statistics 2e','https://openstax.org/details/books/introductory-statistics-2e','阅读抽样、概率、置信区间、假设检验与回归章节。'],materials:['MIT OCW · Introduction to Solid State Chemistry','https://ocw.mit.edu/courses/3-091sc-introduction-to-solid-state-chemistry-fall-2010/','按原子、键合、电子材料、晶体和扩散学习，使用自测题。'],climate:['NOAA · Climate Education','https://www.noaa.gov/education/resource-collections/climate','以气候统计、碳循环、观测证据与变化机制为检索主线。'],nasa:['NASA · Learning Resources','https://www.nasa.gov/learning-resources/','在STEM和地球科学资源中寻找观测、模型和课堂活动。'],who:['WHO · Vaccines and immunization','https://www.who.int/health-topics/vaccines-and-immunization','阅读免疫和公共卫生证据；不将课程示例用于个人诊疗。'],cs50:['Harvard · CS50x','https://cs50.harvard.edu/x/','从C、内存、算法、数据结构进入，独立完成习题和项目。'],algorithms:['MIT OCW · 6.006 Introduction to Algorithms','https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-fall-2011/','结合讲义、习题和考试学习复杂度、排序、图和动态规划。'],ml:['An Introduction to Statistical Learning','https://www.statlearning.com/','作者提供开放教材；学习回归、分类、重抽样、树及无监督方法。'],deep:['Deep Learning · 作者开放教材','https://www.deeplearningbook.org/','先读线性代数、概率和机器学习基础，再读优化与深度网络。'],owasp:['OWASP · Top 10','https://owasp.org/projects/top-ten','从风险类别进入原始文档；清单不能替代具体威胁建模。'],sre:['Google · Site Reliability Engineering','https://sre.google/sre-book/table-of-contents/','重点读SLO、监控、过载、共识、数据完整性和发布工程。'],cloud:['NIST SP 800-145 · Definition of Cloud Computing','https://csrc.nist.gov/pubs/sp/800/145/final','核对服务模型、部署模型和云计算基本特征。'],ethereum:['Ethereum · Developer Documentation','https://ethereum.org/developers/docs/','阅读账户、交易、共识、智能合约和安全；以测试环境练习。'],pi:['Raspberry Pi · Documentation','https://www.raspberrypi.com/documentation/','从硬件、GPIO、微控制器和安全文档入门，确认电气规格。'],mdn:['MDN · Learn Web Development','https://developer.mozilla.org/en-US/docs/Learn_web_development','按语义HTML、CSS、JavaScript、可访问性和工具链学习。'],wai:['W3C WAI · Tutorials','https://www.w3.org/WAI/tutorials/','阅读页面结构、表单、图像和表格教程，进行键盘与辅助技术检查。'],quantum:['IBM · Quantum Learning','https://quantum.cloud.ibm.com/learning/en','从Basics of Quantum Information学习线性代数、测量与电路。']};
const packs=[];
function D(id,question,prerequisites,connections,refs,lessons,hours=120){packs.push({domainId:id,question,prerequisites,hours,outcomes:lessons.map(x=>`能独立完成「${x.title}」中的算例、解释假设并通过迁移练习`),connections,sources:refs.map(k=>({title:S[k][0],url:S[k][1],note:S[k][2]})),stages:lessons.map((x,i)=>({...x,key:['beginner','intermediate','advanced'][i]}))});}
function L(title,lesson,terms,example,exercise,quiz,project){return {title,lesson,concepts:terms.map(([term,explanation])=>({term,explanation})),workedExample:{question:example[0],reasoning:example.slice(1,-1),answer:example.at(-1)},exercise:{question:exercise[0],answer:exercise[1],rubric:[`说明${terms[0][0]}的适用条件，推理能被复核`,`用${terms[1][0]}检查结论，标出数据或模型局限`]},quiz:[{question:quiz[0],options:quiz[1],correct:quiz[2],explanation:quiz[3]}],project:{title:project[0],brief:project[1],deliverables:[`一份含${terms[0][0]}与${terms[1][0]}的分析或实现`,`附原始输入、计算步骤、核验结果和失败边界`],rubric:['问题明确、数据和来源可追溯','方法匹配问题、结果有误差或反例检验']},prompts:[`请围绕「${title}」当我的导师。先问一个检验${terms[0][0]}的具体问题，等我回答后逐步追问，不直接替我完成作业；用${terms[1][0]}给一个反例，区分事实、假设和推断。引用时给原始出处，不确定的数值或资料明确说待核实。`]};}

D(36,'怎样在不确定收益下配置资产，而不是把历史涨幅当作未来保证？',['复利、期望和方差','资产负债表与现金流'],[33,37,49],['finance','statistics'],[
L('复利、实际收益与风险', ['投资收益率必须同时说明时间、现金流和购买力。单期收益率是期末价值加期间分配减期初投入，再除以期初投入；多期不能直接把百分比相加，要连乘增长因子。名义回报没有扣除通胀，实际回报用(1+名义回报)/(1+通胀)-1计算。费用和税也会改变可实现收益。','风险既包括价格波动，也包括无法按期支付生活支出的流动性风险。把应急资金和长期资本分开，是期限匹配问题。预期收益是概率加权的可能结果，并不是承诺；历史均值只是估计。对个人资产的具体选择还取决于约束，本课程算例均为虚拟数据，不构成购买建议。'],[['复利','每一期收益进入下一期本金，增长因子相乘。'],['实际收益','名义增长扣除价格水平变化后的购买力增长。']],['虚拟资产先涨20%再跌20%，100元剩多少？','第一年100×1.2=120。','第二年120×0.8=96。','剩96元，总回报-4%，并非0%。'],['名义收益6%、通胀3%时实际收益是多少？','1.06/1.03-1≈2.91%，3%只是近似。'],['两期各收益率相加何时最可能误导？',['复利跨期时','只有一期时','没有资产时','单位相同时'],0,'跨期本金发生变化，必须连乘增长因子。'],['建立购买力台账','用虚拟十年现金流比较名义、实际和扣费回报。']),
L('组合分散与相关性',['组合收益是权重加权的收益，但组合方差还取决于资产之间是否同时涨跌。两资产方差为w²σA²+(1-w)²σB²+2w(1-w)Cov(A,B)。协方差衡量共同变化，相关系数将它标准化为-1到1；低相关资产可能降低总波动，但市场压力下相关性可能上升。','有效前沿表示在给定风险度量下无法再增加预期收益而不增加风险的组合集合。它依赖估计的均值、协方差和约束，输入误差可以使最优权重极不稳定。分散能降低部分非系统风险，不能消除通胀、宏观冲击和极端流动性风险；再平衡还会产生交易成本。'],[['协方差','共同偏离各自均值的方向和幅度。'],['有效前沿','既定输入和约束下，风险与收益不被其他组合同时改进的集合。']],['虚拟两资产各波动20%、等权、相关0，组合波动多少？','方差=0.25×0.04+0.25×0.04=0.02。','标准差为√0.02≈0.1414。','约14.14%，不是20%也不是0%。'],['同样资产相关系数为1时波动多少？','方差=0.02+2×0.5×0.5×0.2×0.2=0.04，波动20%。'],['分散化收益最直接依赖什么？',['资产名字数量','收益相关结构','交易软件颜色','单个历史最高收益'],1,'若所有资产完全同向，增加名字未必降低风险。'],['重建三资产有效集合','用公开历史数据或标注的虚拟数据画风险收益图，并改变相关假设。']),
L('配置政策与稳健检验',['资产配置政策先明确目标支出、期限、流动性和最大可承受损失，再决定可投资资产、权重区间和再平衡规则。绩效比较应使用与风险暴露相匹配的基准。夏普比率用超额收益除以波动，适合部分比较，但对非正态尾部、非流动资产估值和平滑收益可能失真。','回测必须避免只选择存活基金、事后挑参数和提前使用未来数据。把训练期、验证期和最终检验期分开，并计入费用、换手和税收。压力测试可以设定利率上升、股债同跌和收入中断等情景；它检验脆弱性而非预言。优秀配置报告应展示结论对假设变化的敏感性。'],[['再平衡','按事先规则恢复权重，控制暴露而非保证择时获利。'],['前视偏差','回测在当时使用了实际上尚未知道的信息。']],['虚拟组合目标股债各50%，股票从50涨至75、债券仍50，怎样恢复权重？','总值125，目标各62.5。','卖12.5股票，买12.5债券，未计费用。','交易后各62.5；这是风险规则而非收益保证。'],['用2025年才公布的财务数据构建2024年组合有什么问题？','存在前视偏差；应按数据实际可获得日期滞后使用。'],['高回测收益能否证明策略可靠？',['能，收益足够高即可','不能，需样本外与成本检验','能，样本越短越好','不能做任何比较'],1,'数据选择、过拟合与成本可能制造虚假优势。'],['撰写投资政策与审计报告','用虚拟家庭约束完成配置规则、压力情景、回测偏差审计，不推荐真实产品。'])]);

D(37,'人们为何系统性偏离理性选择，怎样检验而非给行为贴标签？',['概率与期望值','相关和因果区别'],[3,36,44],['econ','statistics'],[
L('参照点与损失厌恶',['传统期望效用理论用结果及其概率描述选择，行为经济学进一步研究人如何表述和感知这些结果。前景理论强调参照点：同一财富水平可被体验为收益或损失。损失厌恶描述许多情境下相同金额损失带来的影响大于收益，不代表每个人、每种任务都有固定的二倍系数。','框架效应是等价问题因表达方式不同而改变选择。解释一个决策时要先检查信息、预算和激励，不能把不同选择一律归为偏差。若两种方案的真实风险不同，偏好差异可能是合理的。行为机制需要通过控制比较来判断，而不是仅凭一次事后故事。'],[['参照点','个体将结果编码为收益或损失时采用的基准。'],['框架效应','逻辑等价的表达改变选择倾向。']],['一项措施说成功率90%，另一说失败率10%，两者概率不同吗？','在成功与失败互斥且穷尽时，1-0.1=0.9。','表达改变注意对象，但未改变概率。','概率相同；若选择不同，可研究框架影响。'],['产品从100降到80再称上涨到90，消费者感到涨价是否证明不理性？','不能；需明确参照点、可替代商品、信息和实际预算，不能由感受直接判断福利。'],['损失厌恶能否直接给每个人设定固定参数？',['能，永远是2','不能，要测量且依情境','能，只取年龄','不能研究损失'],1,'理论提出机制，参数要靠数据估计。'],['设计等价框架问卷','写出两个等价表达，预注册比较指标及排除条件。']),
L('跨期选择与现在偏好',['指数贴现把未来效用乘以δ的时间次方，保持不同日期之间相同的相对耐心。准双曲贴现常用βδ^t表示未来权重，其中β小于1可描述对眼前的额外偏爱。现在偏好可能产生动态不一致：今天计划下周储蓄，到下周又想推迟。','承诺装置通过提前改变后来的选择集合帮助实现较早目标，但并非所有限制都提高福利。收入波动、借贷限制和不确定性也会导致短期选择。设计干预要区分这些机制，并允许退出；只观察一个人未储蓄不能推断他缺少自律。'],[['指数贴现','每推迟一期按相同因子折算效用。'],['现在偏好','对立即兑现结果赋予额外权重，可能导致时间不一致。']],['虚拟选择：今天100与明天110，若β=0.8、δ=1，按线性效用选哪个？','今天价值100。','明天在今天的价值为0.8×110=88。','模型预测选今天100，参数是假设而非个体诊断。'],['若δ=0.95，100一年后相当于今天多少？','指数贴现下为95；这只是效用线性且无风险的简化。'],['现在偏好与什么现象最相关？',['时间不一致','所有价格相同','样本必然随机','收益没有风险'],0,'临近兑现时改变计划，是模型的关键预测之一。'],['比较两种储蓄干预','为虚拟群体比较提醒与自愿承诺，列出机制、退出权和福利指标。']),
L('随机实验、助推与福利',['默认选项改变不主动选择者的结果，可能通过惰性、认知成本或对建议的理解发挥作用。要区分默认本身与同时改变的信息、手续或费用。随机分配使干预组和对照组在期望上可比，意向治疗效应按原始分组比较，不因个体未遵从就事后换组。','实验平均效果不等于每个人都受益。需检查样本选择、失访、异质性、持续时间和推广成本。福利判断还涉及自主性、透明度与分配影响。助推不能替代解决高费用、资源短缺或不公平制度的问题；政策报告必须把行为结果与价值判断分开呈现。'],[['意向治疗','按最初随机分组估计干预政策的平均效果。'],['外部效度','在其他人群、时间和制度中是否仍成立。']],['虚拟实验两组各100人，干预组40人参加，对照组25人参加，ITT是多少？','干预率40/100=40%。','对照率25/100=25%。','差15个百分点；不能仅凭此判断统计精度。'],['若只比较实际接受提醒者与没接受者，可能有什么偏差？','接受者可能本来更积极，破坏随机可比性；应先按分配组估计ITT。'],['参与率从25%到40%，增加多少个百分点？',['15','60','40','25'],0,'相对增幅60%，绝对差15个百分点，不能混用。'],['撰写透明助推评估','设计随机分配、知情说明、失访检查、异质性与自主性评估。'])]);

D(38,'工资、就业与收入差距如何由生产率、制度和议价共同形成？',['供需曲线与边际量','均值、中位数和分位数'],[31,37,39],['econ','economics'],[
L('劳动需求与工资形成',['企业雇佣劳动不是因为劳动人数本身有价值，而是额外劳动能增加可销售产出。在产品与劳动市场竞争等简化条件下，雇佣增加到劳动边际收益产品等于工资的附近。技术、产品需求和资本配套都会移动劳动需求，工资差异不能单独归因于努力。','劳动供给涉及收入与闲暇的权衡，也受照护义务、交通、健康和就业信息约束。更高工资既提高休闲的机会成本，也提高可购买休闲的收入，两个效应方向可能不同。劳动市场并非普通商品市场的机械复制，合同不完全、雇主权力和社会规范影响实际结果。'],[['边际收益产品','额外一单位劳动增加的产出收入。'],['保留工资','在既定条件下愿意接受工作的最低工资水平。']],['虚拟工厂多雇一人每天多产10件，每件边际收入20元，新增非工资成本30元，最高可付多少工资？','新增收入10×20=200元。','扣其他新增成本30元。','简化上限170元/天；不含长期风险。'],['产品价格下降而产量技术不变，对劳动需求通常如何？','边际收益产品下降，其他条件不变时劳动需求减少。'],['劳动需求来自什么？',['产品需求的派生需求','人数越多越好','员工偏好','固定不变常数'],0,'雇佣决策取决于额外劳动的收益与成本。'],['画一张岗位需求图','用虚拟生产数据计算边际产出、收益产品和雇佣区间。']),
L('人力资本、信号与歧视',['教育工资溢价可能同时包含技能提升、能力筛选、家庭资源与劳动力市场信号。比较受教育者与未受教育者的平均工资，只得到相关性；需要处理入学选择、地区和行业差异，才有机会解释因果回报。不可把群体均值当成对个人价值的判断。','歧视可来自偏好、统计推断或制度性障碍。相同简历随机改变群体线索的审计实验能研究招聘回访差异，但未必代表最终雇佣、工资和所有行业。收入差距分解可描述可观测特征贡献，剩余项不自动等于纯粹歧视，因为模型和遗漏变量都影响它。'],[['人力资本','通过教育、训练和健康积累的生产能力。'],['信号','可观察资格传递关于不可观察能力的信息。']],['虚拟数据大学组月薪8000、非大学组6000，能说读大学因果增加2000吗？','差值为2000，但两组可能能力与地区不同。','需可比对照或可信研究设计。','只能先报告未调整关联差，不能直接声称因果。'],['随机给相同简历分配不同姓名，能检验什么？','在该招聘情境下，姓名线索对回访的平均因果影响；不能概括全部收入歧视。'],['未解释工资差是否必然都是歧视？',['是','否，模型可能遗漏因素','是，只要样本大','否，所以歧视不存在'],1,'残差不等于单一机制，否认歧视同样超出证据。'],['审计一篇教育收益研究','列出估计对象、识别假设、选择偏差和外推边界。']),
L('买方势力、最低工资与分配',['在有搜寻摩擦的劳动市场中，企业可能面对向上倾斜的劳动供给，增加雇佣往往要提高工资，边际雇佣成本高于工资。这样的买方势力模型可以同时产生较低工资和较低就业；适度最低工资有时可能提高二者，但效果取决于水平和市场环境。','政策评估可用双重差分比较受影响与未受影响地区在政策前后的变化。关键是没有政策时二者趋势应可比，还要检查提前反应、溢出和政策同时发生。收入分配分析要分清小时工资、工作时长、税前收入与可支配收入，单一指标无法代表福利全部变化。'],[['买方势力','雇主能在一定范围影响工资而不失去全部劳动力。'],['双重差分','处理组前后差减对照组前后差，在识别假设下估计政策效应。']],['虚拟就业：政策区100→105，对照区100→102，双重差分多少？','处理组变化+5。','对照组变化+2。','估计+3；成立依赖平行趋势等假设。'],['若政策前两地就业趋势已明显不同，简单双重差分可靠吗？','不可靠，应解释差异、改进对照或研究设计，不能靠公式消除偏差。'],['最低工资在所有模型都必然减少就业吗？',['是','否，取决于市场结构与水平','只看名义值即可','与供求无关'],1,'竞争和买方势力模型可给出不同预测，需实证检验。'],['完成最低工资政策备忘录','比较两种市场模型，并设计带前趋势检查的政策评估。'])]);

D(39,'怎样区分贫困的个人表现、结构机制和可验证的政策效果？',['百分比、分位数与购买力','相关不等于因果'],[38,60,31],['econ','economics'],[
L('贫困线与多维剥夺',['绝对贫困线按一组基本需要或固定购买力阈值识别贫困，相对贫困线则参照社会收入分布。贫困发生率H=q/n只统计人数，不反映离贫困线有多远；贫困缺口进一步考虑收入短缺。比较国家时需要统一价格、时间与家庭规模，名义汇率不能直接代表生活购买力。','收入只是手段。健康、教育、安全、饮水和参与机会的剥夺可能相互强化。同样家庭平均收入下，成员内部的资源分配仍可能不平等。测量方式决定哪些人被看见，因此政策评估应同时报告阈值、缺失数据和敏感性，而不是只发布一个看似精确的排名。'],[['贫困发生率','低于明示贫困线的人口比例。'],['贫困缺口','相对于贫困线的收入短缺程度。']],['虚拟三人收入40、80、180，贫困线100，H是多少？','前两人低于线，q=2。','人口n=3。','H=2/3；不能据此得出短缺总额。'],['按同样收入计算人均标准化缺口。','缺口为0.6、0.2、0，平均约0.267。'],['贫困发生率会反映穷人变得更穷吗？',['始终会','人数不变时未必','一定翻倍','与贫困线无关'],1,'它只数是否越线，不计越线距离。'],['建立贫困指标比较表','用虚拟家庭数据比较发生率、缺口与教育健康剥夺。']),
L('信贷约束与贫困陷阱',['贫困陷阱是低资源导致低投资、低生产率又导致低资源的自我强化机制，并非所有贫困都属于陷阱。固定成本、营养门槛、风险暴露和信贷约束可能使不同初始条件产生不同长期轨迹。必须展示门槛或动态证据，不能用循环叙述代替机制证明。','小额信贷降低融资障碍，却不自动创造高回报项目。借款人仍面临需求、技能、风险和偿还压力。发展政策可能需要把现金、资产、培训与保障组合使用。研究平均效应时也要考察债务负担、群体异质性和持续时间，零平均效应不等于无人受益或无人受损。'],[['信贷约束','有回报机会但无法按可接受条件筹资。'],['贫困陷阱','初始资源不足通过反馈维持低收入状态。']],['虚拟设备成本1000，家庭储蓄300、最多贷款400，能购买吗？','可用资金300+400=700。','低于1000，缺口300。','即使预计项目盈利，约束仍使投资不可行。'],['提供贷款后仍不创业，是否证明缺乏动机？','否；项目风险、需求不足、照护约束和收益预期都可能解释。'],['证明贫困陷阱最需要什么？',['贫困这个词','资源与未来轨迹的非线性机制证据','一个励志故事','贷款一定有效'],1,'持久贫困本身不证明存在门槛型动态。'],['绘制家庭资源反馈图','明确一项门槛、两个反馈，并写出可以推翻陷阱解释的观测。']),
L('因果评估与政策推广',['随机试验可比较现金补助等干预与对照，但随机化单位可能是个人、村庄或学校，标准误必须尊重分配结构。受助者影响邻居会产生溢出，可能使简单组间比较漏掉总效果。失访与执行不遵从要单独报告，不能删除不理想样本以制造成功。','推广决策还要考虑每单位效果的财政成本、地方执行能力和规模扩大后的价格变化。一个村庄的成功未必代表全国均衡效果。优秀政策分析应说明谁获益、谁承担成本、持续多久，并将因果识别、成本效益和公平判断分开，使政策取舍可以被讨论和复核。'],[['溢出效应','干预影响未直接受助者，改变对照含义。'],['成本效果','每实现一个明示结果单位所需的成本。']],['虚拟政策成本10万元，使20户额外脱离贫困，每户成本多少？','先明确20户是相对反事实的净增。','100000/20=5000。','每额外脱贫户5000元，仍需检查持续性。'],['若按村随机却把每户当独立样本，可能怎样？','忽略村内相关可能低估不确定性，应使用与集群设计匹配的推断。'],['小规模试验有效便可无条件全国推广吗？',['可以','不能，需执行和一般均衡检验','只看媒体支持','不需要成本'],1,'规模变化会改变价格、资源与执行条件。'],['写一份扶贫试点评估方案','定义反事实、集群、溢出、成本与长期随访指标。'])]);
D(40,'数字平台如何创造价值，同时改变市场力量与数据分配？',['供需与边际成本','互联网基本结构'],[41,63,65],['econ','marketing'],[
L('数字商品与平台两侧',['数字商品常有高固定研发成本与低复制成本，但获客、审核、带宽和计算并非免费。平台连接不同群体，其价值可能取决于另一侧参与数量，这叫跨边网络效应。同侧用户增加也可能带来竞争或拥挤，网络规模并不总是越大越好。','平台定价可以补贴一侧吸引另一侧付费，因此单侧低价不足以判断盈利或掠夺。交易额是平台促成的总交易价值，收入通常只是抽成或服务费的一部分，利润还要扣除成本。学习数字商业首先应画清谁给谁提供什么、谁付钱、谁承担风险。'],[['跨边网络效应','一侧参与增加改变另一侧价值。'],['边际复制成本','多服务一单位数字内容的额外成本。']],['虚拟平台月交易额100万、抽成5%，收入多少？','平台只收交易额的5%。','100万×0.05=5万。','收入5万元，不是100万元，且未扣成本。'],['交易额翻倍但补贴增长更快，利润一定增长吗？','不一定；利润取决于收入减补贴与其他成本。'],['平台交易额与收入通常怎样？',['必然相等','抽成模式下不相等','收入永远为零','与商业模式无关'],1,'交易额衡量撮合规模，收入衡量平台取得的报酬。'],['画一个双边市场价值流图','标明两侧用户、价格、数据和潜在负外部性。']),
L('多归属、转换成本与竞争',['用户同时使用多个平台叫多归属；转换成本来自历史数据、关系网络、学习投入和合约。强网络效应加高转换成本可能形成进入壁垒，但互操作、差异化和多归属会削弱锁定。不能仅凭市场份额推断市场力量，还要定义相关市场与用户替代选择。','数据可能改善匹配和预测，却存在质量、隐私与边际价值递减。更多数据不必然胜过更好的实验和模型。平台兼任规则制定者与参与者时，自我优待可能影响竞争。分析应比较效率收益与排他风险，区分理论可能性和已观察到的证据。'],[['多归属','同一用户同时参与多个竞争平台。'],['转换成本','用户切换服务时额外承担的损失与投入。']],['虚拟平台A收费10元，转B每月省3元但迁移需30元，静态回本多久？','迁移一次成本30元。','每月节省3元。','10个月，未计折现及功能差异。'],['可导出数据一定消除全部锁定吗？','否；社交关系、协作习惯和互补服务仍可能造成转换成本。'],['互操作可能主要降低什么？',['所有研发成本','部分网络锁定和转换成本','用户数量','全部隐私风险'],1,'连接和迁移更容易，但不自动解决质量与隐私问题。'],['比较两平台竞争条件','列出多归属、转换成本、数据优势和进入者可行路径。']),
L('数字治理与社会成本',['数字服务的私人收入不一定涵盖全部社会影响。注意力占用、错误信息扩散和数据泄露属于应进入评估的外部成本，便利、匹配效率与知识传播则可能是收益。因果估计需要区分平台使用与用户自我选择，不能由活跃用户的特征直接推断平台造成的结果。','治理可涉及透明度、数据最小化、可携带性、竞争规则和风险审计。不同措施会改变创新成本、隐私与可及性，需要明确权衡。设计指标时应同时测量用户收益、分配和风险，而不是把增长等同于福祉；审计还需说明数据访问权限和可复现程度。'],[['外部成本','未由交易当事人充分承担的他人损失。'],['数据最小化','只收集实现明示目的所必需的数据。']],['虚拟新推荐使时长增20%、满意度降5%，能称产品福利提高吗？','时长是行为指标，不等于福利。','满意度下降提示目标冲突。','需合并收益、风险和自主选择证据判断。'],['要检验推荐算法对满意度的因果影响，应怎样设计？','随机分配算法版本，预设满意度与风险指标，记录失访和异质性。'],['数字业务最充分的成功指标是哪项？',['只看时长','综合价值、风险与分配','只看注册数','只看下载数'],1,'单一增长指标可能掩盖社会与用户成本。'],['完成数字平台责任评估','提出一个可审计规则，比较用户、商家与平台的成本收益。'])]);
D(41,'企业如何为顾客创造价值，并从价值中获得可持续回报？',['收入、成本与利润','机会成本'],[42,47,48],['management','venture'],[
L('价值创造与价值获取',['顾客愿意支付的上限与生产机会成本之差构成交易可创造的总剩余。企业收入不等于顾客价值，利润也不等于全部社会贡献。若顾客愿付100元、价格70元、成本40元，顾客剩余30元，企业毛剩余30元，总剩余60元；这只是简化的单笔交易模型。','企业要可持续，既需创造顾客重视的结果，也需获得足以覆盖投入的报酬。利润可能来自效率、创新和承担风险，也可能来自信息不对称或市场力量，来源需要具体辨别。外部污染或隐私损害若未计入成本，私人盈利就可能高估社会净价值。'],[['价值创造','扩大顾客愿付与资源机会成本之间的差额。'],['价值获取','企业通过价格、合同等机制保留的价值份额。']],['虚拟服务愿付120、价格90、成本50，各方剩余多少？','顾客剩余120-90=30。','企业剩余90-50=40。','总剩余70，未计外部影响。'],['涨价10元但销量不变，总创造价值必然增加吗？','不一定；愿付和成本不变时只是顾客与企业间重新分配。'],['价值创造和涨价的关系？',['完全等同','涨价可能只改变分配','涨价必然创新','价格与成本永远相等'],1,'总剩余取决于愿付与资源成本，价格影响分配。'],['拆解一项日常服务','明示顾客任务、替代品、愿付依据与资源成本。']),
L('单位经济与现金循环',['单位经济分析把收入和可归属的变动成本对应到一个订单、顾客或服务周期。贡献毛利是收入减变动成本，用于覆盖固定成本。规模扩大若每单位仍亏损，未必会自动改善；必须说明成本下降、定价或复购机制，而不能只用未来规模作解释。','利润与现金流不同。赊销可先确认收入后收款，库存先消耗现金再销售。现金转换周期通常是库存天数加应收天数减应付天数，它帮助理解企业为何盈利仍缺钱。比较公司时要检查会计口径、资本支出和一次性项目，不能混用毛利、营业利润与自由现金流。'],[['贡献毛利','单位收入减单位变动成本。'],['现金转换周期','从支付采购到收回销售现金的近似净时间。']],['虚拟商品单价100、变动成本60、固定成本2万，保本销量多少？','贡献40元/件。','20000/40=500。','500件；假定售价与成本不随量变。'],['库存30天、应收20天、应付15天，现金周期多少？','30+20-15=35天。'],['利润为正是否确保现金充裕？',['确保','不确保，收款和存货占用可能很大','只有制造业才不同','会计利润就是现金'],1,'确认收入与实际现金收付可能不同步。'],['完成小生意现金模型','用虚拟订单、库存和赊销条件计算保本点与资金缺口。']),
L('商业系统与可持续优势',['企业是一组相互依赖的活动：产品设计影响生产复杂度，渠道影响获客和服务成本，售后反馈又影响研发。单独复制某一做法未必复制整体绩效。活动之间的配合、组织能力和学习曲线可能构成优势，但也可能造成路径依赖，妨碍适应变化。','判断商业模式应同时检验顾客价值、单位经济、竞争反应与治理责任。敏感性分析改变售价、留存和成本，观察关键假设何时失效。对商业案例的成功解释要防幸存者偏差：应寻找类似策略失败的对照，而不是由结果倒推每一个决定都正确。'],[['活动配合','经营活动相互增强而非孤立优化。'],['敏感性分析','改变关键输入以检查结论稳健性。']],['虚拟企业每件贡献40、月销1000、固定成本3万，若销量降25%利润多少？','原利润40000-30000=10000。','新销量750，贡献30000。','利润为0，说明接近经营杠杆阈值。'],['成功企业用了订阅制，能证明订阅制导致成功吗？','不能；需对照顾客、竞争、成本和选择机制，并寻找失败案例。'],['系统优势最难通过哪种方式理解？',['活动关系图','孤立抄一个功能','成本与价值分析','比较失败样本'],1,'单点模仿忽略活动间的互补和约束。'],['撰写商业系统诊断','画活动关系，做三种情景与失败条件检验。'])]);
D(42,'怎样把商业模式画布转化为可以证伪的经营假设？',['贡献毛利与现金流','用户访谈基础'],[41,44,45],['venture','management'],[
L('九要素与价值流',['商业模式画布通常包括客户细分、价值主张、渠道、客户关系、收入来源、关键资源、关键活动、关键伙伴和成本结构。它的作用是把相互依赖的经营逻辑放在一张图上，而非填满九格就证明可行。每格要写具体群体、任务、行为或资源，避免只写品质好、用户多等口号。','顾客、使用者和付款者可能不是同一人。教育服务可能由家长付款、学生使用、学校影响采购，因此价值主张和渠道需分别说明。画布应显示资金、服务和信息如何流动，并明确哪些关系有事实支持，哪些只是团队猜想。'],[['价值主张','面向特定群体解决特定任务所提供的可验证利益。'],['客户细分','需求、行为或支付机制具有共同特征的群体。']],['虚拟企业给公司卖员工培训，使用者与付款者是谁？','员工使用课程。','企业采购部门或管理者付款和决策。','至少两种角色，不能只写企业用户。'],['把所有成年人写成客户细分有什么问题？','过于宽泛，任务、渠道、支付意愿和约束不同，无法形成可检验假设。'],['画布首先是什么？',['可行性证明','经营假设的可视化','财务审计报告','唯一战略'],1,'填图组织思考，不替代市场和财务证据。'],['为一项服务画九格','每格用一条具体陈述并标注证据等级。']),
L('假设优先级与实验',['不是所有假设都值得同时验证。先找一旦错误就使项目失败、但目前证据最薄弱的假设，例如目标顾客是否愿意为结果付费。访谈可揭示问题和现有行为，真实承诺或购买更接近支付意愿；问愿不愿意支持通常会产生礼貌和假设偏差。','实验需事先写清目标人群、干预、指标、成功阈值与停止规则。落地页点击说明注意力，不直接证明复购或利润；预购说明更强承诺，但仍涉及退款与履约。每项证据只支持它实际测量的假设，不能把一个漏斗指标推广为整个模式成功。'],[['致命假设','失败会使商业逻辑无法成立的核心条件。'],['证据强度','行为与目标结果之间的距离及测量可信度。']],['虚拟落地页1000访客、100留资、10付款，付费转化率多少？','相对访客10/1000=1%。','相对留资10/100=10%。','两个分母不同，应分别报告。'],['100人表示喜欢，能否代替付费试验？','不能；态度与实际交易不同，应测试有成本的真实选择。'],['点击率最高能直接证明什么？',['复购','用户采取了点击行为','长期盈利','顾客终身价值'],1,'必须区分注意、试用、付款与持续使用。'],['设计一轮画布验证','挑三项高风险假设，各配一个指标、阈值与反证条件。']),
L('模式迭代与边界条件',['商业模式迭代应基于机制证据，而不是只要增长不达标就更换口号。若有需求但获客成本高，可以检验渠道；若试用好但复购低，要研究持续任务、质量或替代品。多项同时变化使结果难归因，应保持变更记录，并设计可比较的版本。','规模化要求单位经济、交付能力和责任边界同时成立。合作伙伴退出、渠道集中或隐私限制可能使原本盈利的模式失效。优秀毕业作品应把画布、证据台账和财务模型连接起来，明确哪些假设已经被支持、哪些仍未验证，以及何种结果会触发停止或转向。'],[['转向','依据关键假设变化重新配置商业逻辑。'],['渠道集中风险','过度依赖少数分发或采购渠道形成的脆弱性。']],['虚拟渠道A占80%订单，若A订单减半，总订单降多少？','A贡献从80降至40。','其他20不变，总量60。','总订单下降40%，说明集中风险。'],['涨价、改产品、换渠道同时做后转化上升，能单独归因涨价吗？','不能；需分离变更或承认只能评估组合效果。'],['迭代最需要保留什么？',['只保留成功截图','假设、变更与证据记录','删除失败数据','每周改全部要素'],1,'可追溯记录能避免事后合理化并支持学习。'],['交付可审计商业模式','提交画布、实验记录、单位经济和转向决策规则。'])]);
D(43,'营销怎样匹配真实需求，如何区分品牌影响与促销噪声？',['比例与贡献毛利','基本调查偏差'],[44,37,63],['marketing','statistics'],[
L('细分、定位与营销组合',['市场细分按需求、行为、使用场景或约束划分人群，目标市场选择决定优先服务谁，定位说明相对替代品提供何种独特利益。人口统计特征可能方便描述，却不总解释购买原因。定位必须能够影响产品、价格、渠道和传播，而不是只写一句响亮标语。','营销组合常用产品、价格、渠道、推广四方面组织决策。广告只能影响其中部分环节；若产品无法解决任务，持续加曝光可能放大负面体验。品牌是顾客对来源、质量和意义的知识结构，标志是识别符号，两者不能等同。需要从顾客实际选择和体验中验证定位。'],[['定位','目标顾客心中相对替代方案的差异化价值。'],['营销组合','产品、价格、渠道、推广的协调决策。']],['虚拟两组顾客一组重便携一组重续航，单一低价宣传为何可能无效？','两组核心任务不同。','价格信息未解释任务收益。','应分别检验便携或续航价值，不能只按年龄划分。'],['品牌logo更新能直接证明品牌价值增加吗？','不能；需测认知、偏好、体验与选择变化。'],['定位最需回答什么？',['字体颜色','对谁、相对谁、何种利益','创始人喜好','广告预算大小'],1,'定位围绕顾客、替代品和价值差异。'],['完成定位对照表','采访五位自愿参与者，记录现有替代与任务，提出可证伪定位。']),
L('漏斗、归因与增量',['获客漏斗可分为曝光、访问、注册、购买和复购，每一层转化都要明确分母和时间窗口。获客成本CAC应与同一口径下新增顾客对应，不能把所有广告点击当付费顾客。顾客终身价值LTV应使用贡献而非收入，并考虑留存、折现与服务成本。','归因模型把已有转化分给接触点，增量实验则问若没有营销还会发生多少转化，两者问题不同。最后点击可能拿走本来会自然购买的功劳。可以用随机留出组估计增量，并检查渠道之间的溢出。短期销售提升还可能只是将未来购买提前。'],[['CAC','为获得一个定义明确的新顾客所付的获客成本。'],['增量效果','营销导致的结果与无营销反事实之间的差。']],['虚拟广告花1万元，处理组100人购买、同规模对照80人购买，增量CAC多少？','额外顾客100-80=20。','10000/20=500元。','增量CAC500元，不能按100人算100元。'],['若每月贡献20元、平均存续10个月，未折现简化LTV多少？','200元，需说明留存和贡献稳定的假设。'],['最后点击归因等于因果贡献吗？',['等于','不等于','只要软件显示就等于','无需反事实'],1,'接近转化的触点可能只是捕获已有需求。'],['做营销增量预算表','用虚拟渠道数据区分归因销量、增量销量与贡献。']),
L('品牌资产与可信实验',['品牌资产可体现为知名度、联想、质量感知、忠诚和对价格的反应，但不同测量工具覆盖的维度不同。品牌追踪需要固定样本定义和问题口径；一次热点曝光可能提高认知却损害信任。长期效果应结合顾客体验与竞争变化，不能只用短期点击评价。','营销研究要控制多重比较、季节性和样本选择。A/B实验在随机化、稳定曝光和无严重干扰的条件下才易解释；事后挑表现最好的分组容易制造假发现。伦理上要避免误导、暗中操纵和侵犯隐私，证据应包括退货、投诉和弱势顾客的影响。'],[['品牌资产','来源于品牌知识并影响顾客反应的价值。'],['多重比较','同时检验很多假设会增加偶然显著结果。']],['虚拟做20次独立无效检验，每次5%误报，期望误报数多少？','每次误报概率0.05。','20×0.05=1。','期望1次；并非保证恰好一次。'],['广告点击上升但退货和投诉也上升，应如何报告？','同时报告，调查承诺与交付是否不符，不能仅以点击宣称成功。'],['品牌健康最好如何判断？',['只看热搜','多维长期指标与因果证据结合','只看logo','只看单日销量'],1,'品牌涉及记忆、信任、体验和长期选择。'],['完成品牌研究方案','定义三维品牌指标、实验及投诉保护机制。'])]);
D(44,'怎样把用户问题转化为产品决策，而不是不断堆功能？',['访谈提问与观察记录','基本比例和实验比较'],[42,43,68],['marketing','venture'],[
L('任务、痛点与需求证据',['用户提出的功能请求只是解决方案线索，不等于根本需求。任务分析要描述在何种情境下，用户希望取得什么进展，目前怎样处理，代价和障碍是什么。访谈追问最近一次具体行为比询问未来是否喜欢更可靠，观察现有替代品有助于发现隐性约束。','问题陈述应包含目标人群、情境、可观察困难和结果指标，避免预先塞入某个功能。样本需覆盖不同使用能力与边缘情境，不能把少数便利访谈当成人群普查。发现研究形成假设，后续还需行为和实验验证；记录反例与原话能减少团队按喜好解释用户。'],[['用户任务','用户在特定情境中希望实现的进展。'],['解决方案偏差','过早锁定功能而忽略问题及替代方案。']],['用户要求导出Excel，应怎样继续问？','询问最近一次导出后要完成什么。','观察是否用于对账、汇报或协作，区分任务。','可能需求是可核验对账，并非文件格式本身。'],['把用户需要一个按钮改成问题陈述。','例如：月末对账人员无法在十分钟内找出差异订单，需验证频率和成本。'],['哪种访谈问题证据更强？',['你会喜欢吗','最近一次怎么做的','你同意我的想法吗','这功能很棒吧'],1,'具体过去行为减少假设和迎合偏差。'],['完成问题发现记录','记录三类用户任务、现有替代、成本与反证。']),
L('优先级、原型与机会成本',['产品优先级本质是在资源约束下选择最值得解决的问题。评分框架如影响、覆盖、信心与投入有助于显式讨论，却不提供客观真理；输入的虚假精度会把猜想伪装成排名。应分离必须满足的约束、风险降低实验和增长机会，并说明不做某项的机会成本。','原型用于降低特定不确定性：纸面草图可测信息结构，可点击原型可测流程，真实最小实现才能检验部分性能或付费行为。可用性测试关注能否完成任务，不等于市场需求验证。观察错误、求助与放弃，比只问满意度更能定位流程障碍。'],[['机会成本','选择某项时放弃的最佳替代价值。'],['原型保真度','原型在表现与行为上接近真实产品的程度。']],['虚拟两功能收益相同，A耗2人周、B耗8人周，应直接选A吗？','先检查估计信心和必要依赖。','若风险、约束和长期价值相同，A资源效率更高。','不能忽略B可能是安全或合规必需项。'],['纸面原型能证明系统能承载十万并发吗？','不能，它适合检验理解与流程，承载能力需真实架构和负载测试。'],['可用性测试主要回答？',['是否存在整个市场','用户能否完成给定任务','利润必然增长','估值多少'],1,'任务完成与需求、商业可行性是不同问题。'],['完成原型测试','为一个任务制作低成本原型，记录五次自愿测试的错误路径。']),
L('指标树与可信决策',['北极星指标应接近持续用户价值，但仍需质量、风险与业务约束作为护栏。把总活跃人数拆成新增、留存和回流，能区分增长来源；队列分析按相近进入时间比较后续行为，避免总体增长掩盖留存下降。指标口径、去重和事件时间必须一致。','A/B实验要事先明确主要指标、最小有意义效果、样本与运行周期，不能看到显著就任意停止。产品决策应综合实验、定性观察和工程成本；不显著不等于效果为零，也可能统计精度不足。优秀产品报告应保留被否定假设，并说明伤害指标、无障碍和隐私如何进入决策。'],[['队列留存','同一进入群体在后续时点仍满足活跃定义的比例。'],['护栏指标','防止优化主目标时损害其他关键价值的约束。']],['虚拟首周100注册，次周30活跃，次周又新来100，总活跃130说明旧客留存多少？','只看首周队列留下30人。','30/100=30%。','旧客留存30%，不是总活跃130%。'],['实验转化提高而错误率翻倍，如何处理？','按预设护栏评估并排查损害，不能仅因主指标提升就发布。'],['不显著意味着？',['效果一定为零','证据不足以在设定阈值拒绝零假设','产品必败','无需样本量'],1,'应结合区间与最小重要效果解释。'],['交付产品决策档案','连接用户证据、指标树、实验结果和上线或停止理由。'])]);
D(45,'创业怎样以有限资源验证机会并管理失败风险？',['收入成本和现金余额','基本用户研究'],[42,44,49],['venture','finance'],[
L('机会与可行性',['创业机会不是新颖想法本身，而是特定人群存在值得解决的问题，且团队可能以可持续方式提供解决方案。可行性分别涉及需求、技术、交付和财务，任何一项缺失都会阻断项目。竞争不仅来自同类公司，也来自用户当前使用的手工流程、延迟处理或不消费。','最小可行产品的最小，是为验证最关键假设保留必要能力，不意味着粗糙或忽视安全。先小范围服务真实用户可降低浪费，但应清楚告知产品边界并保护数据。创业故事常只展示成功者，应比较失败项目和基准率，避免把热情当作市场证据。'],[['机会识别','将问题、可行方案和可获得价值连接起来。'],['最小可行产品','为检验关键经营假设而设计的最小真实交付。']],['虚拟团队做十个功能却不知谁付费，下一步重点是什么？','识别具体付款者和任务。','用可交付的小方案测试付费承诺。','先验证致命需求假设，而非继续扩功能。'],['没人采用时能直接归因为宣传不足吗？','不能，问题、定价、信任、交付和渠道都可能失败，需分解证据。'],['MVP的主要目的？',['证明团队聪明','以较小成本检验关键假设','尽可能低质量','替代所有研究'],1,'最小范围服务于学习与风险降低。'],['编制机会证据表','列出替代方案、付款者、关键假设和最便宜的可行检验。']),
L('跑道、里程碑与单位经济',['现金跑道是现有可用现金除以净消耗速度的粗略时间估计，收入和支出波动时不能机械外推。创业财务应按月列现金流、应付和可能融资延迟，而不是只看年度利润。里程碑要关联风险消除，例如完成可靠交付、证明复购或达到正贡献，而非只统计会议和代码量。','获客、履约、退款和支持成本都应进入单位经济。若每单贡献为负，增长可能加速耗尽现金；若贡献为正但固定成本高，仍需销量和资金支持。资本需求取决于达到下一验证节点需要多久、花多少钱，以及失败时能否及时停止。'],[['现金跑道','在明示消耗假设下资金可维持的时间。'],['里程碑','可验证且能改变项目风险判断的阶段成果。']],['虚拟现金60万，每月支出15万、收入5万，跑道多久？','净消耗15-5=10万元/月。','60/10=6。','约6个月，不含波动、债务和融资费用。'],['每单收入50、变动成本55，卖一万单贡献多少？','-5×10000=-50000元，尚未扣固定成本。'],['订单增长但负贡献不变会怎样？',['必然盈利','可能加快现金消耗','现金不受影响','固定成本消失'],1,'多卖一单位仍增加亏损时，规模本身不能解决问题。'],['做十二月现金压力表','用虚拟数据列基本、乐观、融资延迟三种情景。']),
L('增长、组织与停止规则',['产品市场匹配没有单一神奇数字，应综合目标群体留存、重复购买、主动推荐、交付稳定和贡献经济性判断。早期少数高热情用户可能不代表更广市场。增长实验应围绕已验证价值展开，过早扩张会把需求或交付缺陷放大，造成招聘和固定成本难以回撤。','创始团队需明确决策权、股权归属、知识产权和冲突处理，口头默契不能代替可执行约定。停止规则提前规定哪些现金、质量或需求结果触发缩减、转向或结束。理性停止是资源配置能力，不是个人价值失败；报告应说明受影响员工、顾客与供应商如何被妥善对待。'],[['产品市场匹配','特定群体持续采用且交付经济性可维持的证据组合。'],['沉没成本','已发生且无法因当前选择收回的成本。']],['虚拟已投入100万，未来再投20万期望只回收10万，旧投入应否决定继续？','旧100万已无法收回，是沉没成本。','未来净期望为-10万，若无其他收益不值得继续。','应比较未来方案，不为证明过去正确而追加。'],['试点20人很喜欢就直接扩到十万人有什么风险？','样本选择、渠道不同、交付瓶颈和单位经济未验证。'],['合理停止规则应何时写？',['失败后改写','关键实验和投入前','融资成功后永不改','只由媒体决定'],1,'提前设定能降低情绪和沉没成本对决策的影响。'],['提交创业投资备忘录','给出继续、转向、停止的证据阈值与利益相关者安排。'])]);
D(46,'领导如何让团队围绕共同任务协作而不依赖个人魅力？',['组织目标与角色','基本沟通和反馈'],[47,48,8],['management','ethics'],[
L('目标、角色与协调',['领导力涉及设定方向、协调行动和维持合作，管理还包括资源、流程与控制，二者在实际工作中重叠。团队绩效取决于任务互依、技能互补和信息流，不能只归因于领导性格。目标需说明结果、约束和优先级，角色需明确谁决策、谁执行、谁提供意见。','责任模糊时多人可能重复工作，也可能都以为别人负责。明确接口比不断要求积极主动更有帮助。目标设置过窄会诱发指标替代，例如只追数量牺牲质量。好的领导过程会检查目标冲突、资源与员工实际控制范围，并根据任务成熟度调整支持方式。'],[['任务互依','一个人的成果依赖其他成员输入或行动。'],['角色清晰','职责、权限和接口能被成员共同理解。']],['虚拟两人都认为对方负责发布检查，问题是什么？','发布接口缺少明确责任人。','应分配执行、复核和决策权限。','根因是协调设计，不能只责怪态度。'],['把尽快完成改成可执行目标。','例如周五前交付通过三项质量检查的版本，安全问题优先于新增功能。'],['团队绩效能只看领导魅力吗？',['可以','不行，还需任务、资源和协调','只看演讲','只看服从'],1,'领导行为的效果依赖组织和任务条件。'],['建立团队职责协议','为真实或虚拟项目定义目标、接口和升级机制。']),
L('反馈、心理安全与冲突',['心理安全是成员表达问题、承认错误或提出异议时不必担心不当人际惩罚，并不等于降低绩效要求。若坏消息被处罚，领导可能只收到好消息，风险因此累积。反馈应围绕可观察行为、影响和可改变行动，避免把一次表现归为固定人格。','任务冲突可能改善方案，人身攻击通常破坏合作，两者不能混为一谈。讨论可以先分离事实、解释与偏好，再比较方案。权力差异会抑制低地位成员发言，轮流表达、书面意见与先听后表态可改善信息质量，但仍需观察谁真正拥有决策和申诉权。'],[['心理安全','提出问题和承认错误时免于不当人际惩罚的共享感受。'],['行为反馈','聚焦具体行为和影响而非人格标签的反馈。']],['成员说测试失败被斥责后以后只报成功，发生什么机制？','报告坏消息的个人成本上升。','领导接收信息出现选择偏差。','应保护诚实报告并同时要求改进计划。'],['你不负责应怎样改成可行动反馈？','例如昨天接口变更未通知测试，导致两小时返工；以后变更前在记录中说明并确认。'],['心理安全是否意味着不追责？',['意味着','不意味着，诚实与标准可以并存','意味着没有目标','意味着领导不决策'],1,'安全表达与绩效责任是不同维度。'],['主持一次结构化复盘','分别记录事实、系统原因、可行动改进和责任接口。']),
L('激励、授权与组织诊断',['绩效奖励会改变成员注意力。按单一指标奖励可能诱发刷量、短期化或隐藏风险；难观察的协作贡献也可能被低估。设计激励需考虑可控性、测量误差、团队互依和长期后果，不能假设所有人只受金钱驱动。公平包括结果、程序和解释，三者都会影响合作。','授权不是把责任丢给下属，而是在明确目标、边界、资源与检查点下转移决策权。组织诊断要比较结构、技能、信息和动机的竞争解释，并使用访谈、流程与结果数据交叉核验。优秀分析应指出领导能改变什么、哪些需要制度改造，避免用培训解决所有结构问题。'],[['指标替代','被奖励的量化指标取代原本希望实现的目标。'],['授权边界','成员可自主决策与必须升级的条件。']],['虚拟客服只按结单数奖励，结单变快但重复求助增加，说明什么？','结单数与真正解决问题不一致。','成员可能提前关单。','需加入解决质量与重复联系等护栏，检查工作负荷。'],['授权采购应至少明确哪些条件？','预算、质量标准、可选择范围、需审批阈值、记录与复核责任。'],['所有低绩效都适合用加奖金解决吗？',['是','否，可能是资源或流程瓶颈','是，只要够多','无需诊断'],1,'激励无法代替缺失技能、权限或工具。'],['完成组织诊断报告','比较三种绩效解释，提出带护栏的激励与授权方案。'])]);
D(47,'怎样识别真正瓶颈，用流程和变异管理改善交付？',['平均数和概率','基本成本计算'],[41,56,65],['management','sre'],[
L('流程、产能与瓶颈',['流程由活动、缓冲和接口组成，产能是一定条件下单位时间可完成的最大量。串行流程的长期吞吐受最慢环节限制，提升非瓶颈设备未必增加系统产出，反而可能积累在制品。必须说明批量、工作时长、返工和停机条件，不能把理论产能当实际交付。','利用率是负荷与有效产能之比，高利用率并非唯一目标。当需求和处理时间波动时，接近满负荷可能导致排队迅速增加。改善应先确认顾客需要的结果，区分增值活动、必要控制和可避免等待，避免以局部忙碌代替系统效率。'],[['瓶颈','限制系统吞吐的资源或环节。'],['在制品','已进入流程但尚未完成的单位。']],['虚拟三工序每小时能力10、6、8件，最大稳定吞吐多少？','串行各件需通过全部工序。','第二工序最慢，为6件/小时。','最多6件/小时，未计停机返工。'],['把第一工序从10提到20会使总吞吐翻倍吗？','不会，第二工序6件/小时仍是瓶颈，可能增加排队。'],['串行流程先改善哪里通常更有产出价值？',['最快环节','当前瓶颈','办公室装饰','随机选择'],1,'系统产出受约束环节限制。'],['绘制服务流程图','测量或虚拟设定各环节时间、返工与队列，识别瓶颈。']),
L('Little定律与排队',['Little定律L=λW把稳定系统的平均在制数量、平均吞吐率和平均停留时间联系起来。它要求使用同一系统边界与单位，并考察长期稳定平均；不能把瞬时峰值直接代入。降低不必要在制品可能缩短周期，但若饿死瓶颈资源也会损害吞吐。','排队来自到达与服务的变异。单服务台M/M/1在特定独立指数假设下，平均系统时间为1/(μ-λ)，当到达率接近服务率，等待非线性上升。现实系统未必符合该模型，但其机制说明为什么需要容量缓冲、预约、负载平衡和减少变异。'],[['Little定律','稳定平均下L=λW，连接数量、吞吐和时间。'],['利用率','到达或工作负荷相对于服务能力的比例。']],['虚拟稳定流程平均在制40件、每日交付10件，平均周期多久？','W=L/λ。','40/(10件/日)=4日。','4日，边界和平均口径需一致。'],['M/M/1中每小时到达8、服务10，平均系统时间多少？','1/(10-8)=0.5小时，即30分钟，依赖模型假设。'],['利用率接近100%而存在波动，等待通常怎样？',['趋近零','急剧上升','完全不变','必定没有队列'],1,'有限服务裕量使随机积压更难消散。'],['做容量缓冲实验','比较三种到达率下的等待，说明模型与实际差异。']),
L('质量控制与持续改进',['过程控制区分共同原因变异和特殊原因变异。控制图用过程数据识别异常信号，规格界限则来自顾客或工程要求，两者不能混用；一个统计稳定的过程仍可能持续生产不合格品。改进前要先验证测量系统，避免把仪器误差误认成过程变化。','精益关注顾客价值与流动，持续改进采用计划、实施、检查和调整的循环。根因分析应形成可检验机制，不是重复问为什么直到找到一个应受责备的人。改变流程后应监测质量、交期、成本与员工负荷，防止局部优化把风险转移给下游或顾客。'],[['控制界限','由过程变异估计用于识别异常的统计边界。'],['规格界限','由使用或设计需求规定的可接受范围。']],['虚拟过程均值偏离顾客要求但波动稳定，是否合格？','稳定仅说明变异模式一致。','顾客规格决定是否符合需求。','可能稳定地产生不合格，需要移动均值或缩小变异。'],['为何不能只用返工减少判断改进成功？','返工可能被隐瞒或推给顾客，应同时测缺陷、投诉、负荷和交付。'],['控制图内所有点正常意味着？',['一定满足规格','未发现该规则下特殊原因信号','产品零缺陷','顾客一定满意'],1,'统计受控与符合规格不同。'],['完成流程改进项目','提交基线、测量检查、根因假设、干预与护栏验证。'])]);
D(48,'企业为什么能持续获得优势，又为何会被环境变化打破？',['供需、利润与机会成本','基本组织活动'],[41,46,50],['management','econ'],[
L('行业结构与战略取舍',['战略说明企业选择服务谁、提供什么价值、怎样组织活动以及明确不做什么。行业结构分析考察竞争者、进入者、替代品、供应商和买方如何影响利润分配。五力是问题框架，不是给行业贴好坏标签的自动评分器，市场边界和技术变化都会改变结论。','运营效率是在类似活动上做得更好，战略定位则强调活动组合与取舍。若企业同时承诺最低成本、无限定制和最高服务，可能出现资源冲突。可持续优势需要能解释相对竞争者的价值或成本差异，而不是用成功这一结果反过来定义优势。'],[['替代品','以不同方式满足同一顾客任务的方案。'],['战略取舍','为形成一致定位而主动放弃部分顾客或活动。']],['虚拟影院的替代品是否只有另一家影院？','顾客任务可能是娱乐或社交。','流媒体、游戏和其他活动也可能替代。','需根据任务和替代弹性界定边界。'],['所有顾客都服务为何可能削弱战略？','不同需求可能要求冲突的活动和成本，导致定位模糊与资源分散。'],['战略最不能省略什么？',['口号长度','选择与取舍','排行榜','创始人名言'],1,'资源有限，战略必须决定优先级和放弃项。'],['画行业价值分配图','定义市场、替代品、议价力量与一项明确取舍。']),
L('资源、能力与模仿壁垒',['资源基础观点关注企业拥有或控制的资产与能力。稀缺、有价值且难模仿的资源可能带来优势，但还需组织能够利用它。声誉、学习惯例、互补活动和路径依赖可使复制困难；单项专利或数据数量不自动形成护城河。资源价值也随环境变化。','动态能力强调感知机会、抓住机会和重新配置资源，但若只在成功后说企业有动态能力，解释就无法证伪。应给出可观察流程，例如试验预算、决策速度和资源退出机制，并比较失败案例。能力的成本和适用边界也应纳入，不能把灵活性当作无代价优势。'],[['互补资产','与核心技术共同作用以实现商业价值的资源。'],['路径依赖','过去选择限制或塑造后续可行能力。']],['虚拟公司有优良技术却无渠道，竞争者技术一般但交付完善，谁必胜？','技术价值需要制造、渠道和服务实现。','比较顾客结果与总成本。','不能仅凭技术优劣判断胜者，互补资产关键。'],['大量数据为何未必构成壁垒？','可能质量差、可替代、合法使用受限或边际价值递减，还需分析能力与产品连接。'],['资源稀缺就一定有价值吗？',['一定','不一定，需解决顾客或成本问题','只看价格','无需组织'],1,'稀缺性只是条件之一，价值与可利用性不可缺。'],['完成优势机制审计','对三项资源说明价值、稀缺、可模仿性、组织利用和失效条件。']),
L('情景规划与战略执行',['战略面对不确定性，情景规划用少数相互区别且内部一致的未来组合检验方案，而不是给每个未来编一个故事就当预测。应区分已知趋势、关键不确定性和早期信号，并评价方案在不同情景下的收益、损失与可逆性。','执行需要将战略转成活动、预算、责任和反馈周期。指标若不反映关键机制，可能让组织完成数字却偏离定位。实物期权思维支持先做小规模可逆投入，保留后续扩张或退出权，但期权也要付出试验与等待成本。毕业作品应同时呈现竞争回应和失败时的调整。'],[['情景规划','用多种合理未来测试战略的稳健性。'],['实物期权','分阶段投入保留后续选择的价值。']],['虚拟一次性工厂投资1000万，试点100万可先检验需求，试点价值是什么？','试点提供需求与成本信息。','若失败可避免剩余投入。','价值在降低不可逆决策风险，但需扣试点和延迟成本。'],['为何不能把三个情景的平均值当准确预测？','情景不一定有可信概率，平均值可能对应不存在的环境组合。'],['稳健战略主要追求？',['只在最乐观情景最好','多种合理情景下可接受并可调整','永不改变','忽略竞争反应'],1,'稳健性关注不确定性下的承受与适应。'],['提交战略选择报告','比较三种方案、两个情景、关键指标与退出条件。'])]);
D(49,'融资如何分配现金流、所有权与风险，估值如何避免错觉？',['复利和现金流','财务报表及股权比例'],[36,45,41],['finance','venture'],[
L('债权、股权与资本成本',['债权通常承诺偿付并可能有担保和契约，股权获得剩余索取与相应治理权。企业资产价值的变化由不同证券按约定分配，融资不是免费现金。高风险早期企业常难提供稳定还本能力，股权融资能分担风险，但会稀释原股东并影响控制。','资本成本是资金提供者对风险要求的回报，不是单看合同利率。融资选择还涉及现金流波动、抵押品、信息不对称和破产成本。创业者应把资金用于达到可验证里程碑，匹配资金期限与资产用途；课程讨论机制，具体合同和监管义务需专业审查。'],[['剩余索取权','履行优先义务后对剩余价值的权利。'],['稀释','新增股份使原持有人股权比例下降。']],['虚拟原有100万股，新发25万股，原股东比例多少？','总股数125万。','100/125=80%。','原股东合计80%，被稀释20个百分点。'],['债务利率低是否必然比股权便宜？','否；需考虑违约、偿付压力、担保、契约和风险，不能只看名义利率。'],['股权融资的资金一定不需回报吗？',['一定免费','不是，投资者承担风险并要求回报','没有所有权影响','等于补贴'],1,'没有固定利息不等于没有资本成本。'],['画资本结构支付顺序','用虚拟资产价值情景比较债权与普通股的收益损失。']),
L('投前投后与估值假设',['投后估值在简单普通股融资中等于投前估值加新投入，投资者比例等于新投入除投后估值。现实中优先权、可转债、期权池和分期条款会改变分配，不能只看一个估值数字。完全稀释口径需要明确计入哪些潜在股份。','现金流折现把未来可分配现金按风险和时间折回今天，估值高度依赖增长、利润、再投资和终值假设。可比公司倍数也依赖业务、会计和风险可比性，不能把热门公司的倍数直接套用。应展示区间和敏感性，承认早期企业现金流不确定性很高。'],[['投后估值','简单融资下投前价值加本轮新资金。'],['终值','明确预测期之后现金流价值的估计。']],['虚拟投前800万，投入200万，投资者占多少？','投后800+200=1000万。','200/1000=20%。','20%，假定无期权池调整与特殊条款。'],['把投入200除投前800得25%哪里错？','分母应是融资后整体价值1000，25%混淆投前投后口径。'],['估值最应呈现什么？',['唯一精确数字','关键假设与敏感区间','媒体热度','同业最高倍数'],1,'不确定现金流不能被伪精确数字消除。'],['建立简化估值模型','用虚拟三年现金流与终值，改变增长和折现率检查区间。']),
L('清算优先与激励一致性',['风险投资合同不只规定价格，还规定清算优先、董事席位、保护性条款、归属期和后续融资权。优先权改变退出时现金分配，同一持股比例可以对应很不同的经济结果。分析必须写清参与或不参与、倍数与转换选择，避免把所有优先股视为同一种。','尽职调查要核对收入质量、客户集中、知识产权、团队承诺和资金使用，而不只看增长截图。分期融资可在里程碑后再投入，降低信息风险，也可能引发短期化或谈判冲突。优秀融资报告应计算多种退出情景，并说明创始人、员工和投资者之间的激励是否一致。'],[['清算优先权','特定退出情景下优先取得约定分配的权利。'],['归属期','股权权益随服务时间或条件逐步确定的机制。']],['虚拟投资200万持20%，1倍不参与优先，退出500万，优先还是转换？','优先取得200万。','转普通股得500×20%=100万。','选择200万；未计其他条款与费用。'],['同条件退出2000万，投资者选择多少？','转换普通股取得400万，高于200万优先额。'],['持股20%是否总能拿退出款20%？',['总能','不一定，合同优先权会改变分配','从来不能','只看估值即可'],1,'需按证券条款和退出情景计算。'],['完成融资条款比较','用虚拟条款计算低中高三种退出瀑布与员工激励影响。'])]);
D(50,'当盈利、权利和公共利益冲突时，企业如何作出可辩护选择？',['事实与价值判断区别','利益相关者识别'],[48,43,60],['ethics','management'],[
L('后果、义务与利益相关者',['商业伦理不能简化为是否合法，因为法律可能滞后，合法行为也可能伤害他人。后果论比较行为造成的总体影响，义务论强调不能被收益轻易抵消的权利与责任，德性伦理关注品格和实践。不同框架可能给出不同结论，应把冲突讲清而非假装只有一个算法答案。','利益相关者包括股东、员工、顾客、供应商、社区与环境，但列名单只是起点。需要说明谁受到何种影响、是否有表达和退出机会、成本收益如何分配。事实不确定与价值分歧要分开处理；更多数据可缩小前者，却不一定消除后者。'],[['义务论','以责任和权利约束评估行为，不能只看收益总和。'],['利益相关者','影响企业或受到企业行为实质影响的群体。']],['虚拟公司合法排放但下游居民承担异味，是否无需伦理讨论？','合法仅说明满足部分法律标准。','仍需评估伤害、权利与分配。','不能以合法替代全部道德论证。'],['利润增加能否自动证明裁员方案正当？','不能，还需比较替代、程序、受影响者权益及长期后果。'],['事实争议与价值争议如何处理？',['完全相同','分别核证与说明原则','都靠投票消除','数据越多必定无分歧'],1,'证据与规范理由承担不同论证任务。'],['写伦理冲突地图','用两种框架分析一个虚拟商业决定并保留未解决张力。']),
L('治理、激励与举报机制',['企业伦理行为依赖制度而不仅是个人品质。销售只按签约额奖励，可能鼓励夸大承诺；采购没有利益冲突申报，可能形成偏袒。控制体系需让权限、记录、复核和申诉相互配合，并保护善意报告问题的人，避免将风险报告视为不忠。','代理问题来自决策者的利益与委托目标不一致，信息不对称使监督困难。独立复核、适当激励和透明披露可降低风险，但控制过度也会增加成本。应依据重大性和权力差异设计治理，检查制度在真实压力下是否可用，而不只统计培训人数和签字文件。'],[['利益冲突','个人或关联利益可能妨碍履行职责的情形。'],['代理问题','代理人与委托者目标不一致且难以完全监督。']],['虚拟采购负责人亲属经营供应商，最低应怎样处理？','先披露关系与潜在利益冲突。','由独立者依据公开标准评估并记录。','不能只凭报价低就忽略程序风险。'],['举报邮箱存在但举报者遭报复，机制有效吗？','无效；需保密、独立调查、反报复与可追踪处理。'],['伦理培训人数最直接测量什么？',['真实无违规','培训覆盖而非行为结果','所有治理效果','社会净收益'],1,'活动量不能替代制度运行和结果证据。'],['设计利益冲突流程','写明披露、回避、独立审查、记录和申诉机制。']),
L('责任披露与绿色漂洗',['企业社会责任涉及核心经营对社会和环境的影响，而非只做捐赠。披露指标需说明组织边界、时间、基线与计算方法；只展示强项或改用更有利分母可能误导。碳强度下降不代表绝对排放下降，总产量增加可能超过单位效率改善。','第三方核验、供应链追溯和申诉机制能提高可信度，但应检查核验范围与利益关系。责任项目要与反事实比较，不能把本来会发生的改进全算成贡献。毕业作品应从事实台账、规范论证和治理建议三部分构成，明确不确定性、受损群体和可执行补救。'],[['绿色漂洗','用选择性或误导性环保表述制造超出证据的形象。'],['重大性','对决策或受影响者具有实质意义的议题。']],['虚拟单位排放降20%，产量增50%，总排放怎样？','新强度0.8倍。','新总量0.8×1.5=1.2倍。','总排放增加20%，不能只宣传强度下降。'],['企业捐款能否抵消未补救的劳动侵害？','不能自动抵消；应单独核实、停止和补救侵害，不能用无关好事替代责任。'],['环保声明最需附什么？',['绿色配色','边界、基线、方法与核验证据','广告点击','创始人承诺'],1,'可审计事实比形象表达更能支持责任主张。'],['审计一份责任声明','用虚拟或公开披露检查选择性呈现、边界与补救责任。'])]);
process.once('beforeExit',async()=>{await fs.mkdir(path.join(root,'data/curricula'),{recursive:true});for(const p of packs){await fs.writeFile(path.join(root,`data/curricula/${p.domainId}.json`),JSON.stringify(p,null,2)+'\n','utf8');}console.log(`Authored ${packs.length} domains / ${packs.length*3} stages`);});
D(51,'怎样把自然现象转成可检验的定律，并说明模型何时失效？',['向量、代数与函数','单位换算及基本微积分'],[55,58,70],['physics','nasa'],[
L('运动、受力与守恒',['速度描述位置随时间的变化，加速度描述速度的变化；运动快不等于合力大，匀速直线运动的合力可以为零。牛顿第二定律在惯性系和质量恒定条件下写为F=ma。分析先选研究对象、画受力图、规定方向，再列分量方程，避免把运动方向当成受力方向。','功是力沿位移方向的积分，动能变化等于合外力所做的功。机械能守恒还要求恰当处理非保守力；摩擦把有序机械能转为内能，不是能量消失。动量守恒取决于系统合外冲量，作用与反作用分别作用于不同物体，不能在单个物体受力图上直接抵消。'],[['惯性系','不受合力物体保持匀速直线运动的参考系。'],['机械能','动能与所选系统势能的总和。']],['虚拟2kg物体受水平净力6N，加速度多少？','取水平方向，F=ma。','a=6/2=3。','3m/s²，力和质量均用SI单位。'],['质量1kg从静止无摩擦下降5m，取g=10，末速度多少？','mgh=mv²/2，v=√100=10m/s。'],['匀速直线运动必定意味着？',['没有任何力','合力为零','动能为零','质量为零'],1,'多个力可以相互平衡。'],['完成斜面模型实验','比较有无摩擦的预测，记录单位、误差和能量去向。']),
L('振动、场与模型统一',['简谐振动的回复力近似与位移成正比且方向相反，弹簧模型满足m·d²x/dt²=-kx，角频率为√(k/m)。线性近似使许多系统可用相同数学结构描述，但大振幅、摩擦和非线性会改变频率与衰减。共振来自驱动与系统固有频率关系，实际振幅受阻尼和能量输入限制。','场把空间每一点的相互作用描述为可计算对象。重力场和电场都能产生力，但源、符号和传播性质不同，不能只因形式相似就说完全等同。用对称性、叠加和守恒可简化模型，随后还要通过测量检验；量纲一致是必要检查，却不能证明方程正确。'],[['简谐近似','在平衡附近将回复作用线性化的模型。'],['叠加原理','在线性理论中总响应等于各源响应的和。']],['虚拟弹簧k=100N/m、质量1kg，角频率多少？','ω=√(k/m)。','√100=10。','10rad/s，周期约0.628s。'],['质量增至4kg且k不变，周期变几倍？','T=2π√(m/k)，周期变2倍。'],['量纲正确是否证明公式正确？',['证明','不证明，只排除部分错误','意味着数据无误','无须实验'],1,'无量纲常数或函数形式仍可能错误。'],['比较振动模型与测量','拟合周期和衰减，说明线性范围及残差。']),
L('相对论、量子与科学边界',['经典力学在低速、宏观和适当精度下非常有效，并非现代物理出现后就无用。接近光速时，需要相对论处理时空与能量动量；微观测量则需要量子理论描述状态、演化与概率。不同理论的适用域可以重叠，优秀模型要能解释为何旧理论在其范围内成立。','实验检验依赖测量不确定性、系统误差和模型比较。一个异常点可能来自仪器、数据处理或理论不足，不能立即宣称推翻定律。宇宙学中的观测也要区分直接记录和模型推断。研究报告应给出假设、预测、误差预算与可复核数据，让结论强度与证据相匹配。'],[['对应极限','新理论在特定条件下恢复旧理论预测。'],['系统误差','由测量或分析机制导致的有方向偏差。']],['测量值9.8±0.2与模型10是否明显冲突？','差值0.2。','需明确±0.2是何种不确定性并考虑模型误差。','不能仅凭数值不同就宣称冲突。'],['为何不能用一条超光速新闻标题判断相对论失效？','需复核计时、同步、校准、统计及独立重复，再比较完整理论预测。'],['新理论取代旧理论意味着？',['旧理论所有应用无效','需说明旧理论有效范围','不再需要实验','模型没有边界'],1,'旧模型可作为受控近似继续使用。'],['写一份物理模型比较报告','选择一个经典预测，说明推导、现代修正和实验可分辨尺度。'])],180);
D(52,'原子结构如何解释物质性质，反应为什么发生且快慢不同？',['代数、对数和物质的量','能量与概率基础'],[57,58,59],['chemistry','materials'],[
L('化学计量、键与结构',['物质的量用摩尔计数粒子，质量通过摩尔质量转成物质的量。配平反应遵守原子与电荷守恒，系数表示粒子或摩尔比例而非质量比例。限制反应物决定理论产率，过量原料不会自动全部转成产物；实际产率还受副反应和分离损失影响。','化学键和分子结构决定许多性质。离子、共价与金属键是有用模型，真实键合可以具有混合特征。分子极性取决于键极性与空间几何的共同作用，不是有极性键就必然有分子偶极。结构解释应连接电子、几何和分子间作用，而非只背元素或反应口诀。'],[['限制反应物','按反应比例先耗尽并限制产物数量的反应物。'],['分子极性','电荷空间分布产生的整体偶极特征。']],['虚拟反应2H₂+O₂→2H₂O，3mol H₂和2mol O₂可得多少水？','3mol H₂需1.5mol O₂，氧足量。','氢气为限制反应物。','理论生成3mol水，剩0.5mol氧。'],['CO₂含极性键，为何整体可无偶极？','线性对称结构使两个键偶极相抵消。'],['配平系数直接代表什么？',['质量比例','粒子或摩尔比例','密度比例','任何情况下体积比例'],1,'质量还需乘各物种摩尔质量。'],['完成反应物料衡算','选择安全纸面反应计算限制原料、产率和残余物。']),
L('平衡、自由能与酸碱',['反应吉布斯自由能满足ΔG=ΔG°+RT ln Q，Q由当时组成构成；平衡时ΔG=0且Q=K。平衡不是反应停止，而是宏观组成稳定且正逆过程速率相等。热力学说明趋势与平衡位置，不能独自说明反应在几秒或几千年内发生。','酸碱模型有不同范围，Brønsted酸是质子给体，碱是受体。水溶液pH与氢离子活度有关，稀溶液常用浓度近似。缓冲液由共轭酸碱对抵抗小量酸碱加入，但容量有限。计算需区分强弱、电离平衡和物料电荷守恒，不可对所有溶液套同一公式。'],[['反应商Q','用当前组成按反应计量构成的比值。'],['缓冲容量','缓冲体系抵抗pH改变的有限能力。']],['虚拟稀盐酸浓度0.001mol/L且完全电离，pH约多少？','[H⁺]≈10⁻³mol/L。','pH≈-log10(10⁻³)。','约3；近似忽略活度和水自解离。'],['Q<K时反应朝哪个方向使Q趋近K？','在给定条件下正向净反应有利，直到平衡或约束改变。'],['平衡状态意味着？',['分子完全停止','正逆反应速率相等','产物必须多','温度总为零'],1,'动态过程持续但宏观组成不再净改变。'],['建立酸碱计算检验表','比较强酸、弱酸和缓冲条件，标明近似范围。']),
L('动力学、电化学与实验设计',['速率定律描述浓度与反应速率的关系，反应级数通常需实验确定，不能直接从总反应系数读取。Arrhenius关系连接速率常数、温度和活化能，催化剂提供不同途径降低动力学障碍，但不改变同温同压下的平衡常数。催化只加快达到平衡。','电化学把氧化还原与电势联系，ΔG=-nFE可解释电池做功趋势，实际电压还受组成、内阻和过电势影响。研究要区分热力学开路预测与带负载表现。实验方案先控制温度、浓度和电极条件，使用空白、重复及误差分析，不在无防护条件下开展危险化学操作。'],[['活化能','速率温度关系中表征动力学障碍的参数。'],['催化','改变反应途径与速率而不改变总体平衡的过程。']],['虚拟反应速率v=k[A]²，A浓度翻倍，速率几倍？','代入(2[A])²。','相对倍数2²=4。','4倍，假设温度与k不变。'],['催化剂能否让同温平衡产率必然提高？','不能；它不改变平衡常数，可加快接近平衡或影响并行反应选择性。'],['总反应系数能直接给所有速率级数吗？',['能','不能，一般需实验','只有催化时能','速率不依浓度'],1,'总反应可能由多步机理组成。'],['设计反应速率研究','仅用纸面或公开数据拟合级数、温度效应并比较替代模型。'])],180);
D(53,'生命怎样传递信息、维持功能，并通过进化形成多样性？',['基础化学与概率','阅读图表和比例'],[52,54,59],['biology','statistics'],[
L('细胞、能量与遗传信息',['细胞是生命结构与功能的基本单位，膜通过选择性通透维持内部环境。代谢反应需能量耦联，ATP是常见能量转移分子而不是凭空创造能量。酶改变反应速率，作用依赖结构、环境和底物，不能用一个基因对应一个复杂性状来概括生命机制。','DNA序列可经转录和翻译参与蛋白质产生，但基因表达受调控，RNA也可具有调控或催化作用。遗传信息与细胞环境共同影响表型。中心法则描述信息流的重要框架，不意味着DNA单独决定一切；解释疾病或行为时需区分分子机制、群体关联和环境作用。'],[['基因表达','遗传信息产生功能性RNA或蛋白质的过程。'],['能量耦联','有利过程为不利过程提供驱动力的连接。']],['虚拟DNA编码链5′-ATG-3′对应mRNA起始密码子是什么？','RNA与编码链同序列方向对应。','把T换成U。','5′-AUG-3′；需明确编码链与模板链。'],['两个细胞DNA几乎相同为何功能不同？','基因表达、调控状态、结构和环境不同，导致不同蛋白质与功能。'],['酶最直接改变什么？',['能量守恒','反应速率','平衡常数必然翻倍','遗传密码全部改变'],1,'酶降低动力学障碍而不创造能量或改变反应平衡。'],['画细胞信息与能量图','连接膜、代谢、DNA、RNA与蛋白质，标明因果和调控。']),
L('遗传、选择与群体变化',['自然选择要求可遗传变异与差异繁殖成功，进化是群体跨代遗传组成的变化，不是个体因为需要而主动进化。突变产生变异，遗传漂变、迁移和选择改变频率；小群体中随机漂变影响可能较强。适应度必须相对具体环境和繁殖结果定义。','Hardy-Weinberg平衡提供随机交配、无选择迁移突变且大群体等条件下的参考模型，等位基因频率p、q对应基因型p²、2pq、q²。偏离可提示假设不成立，但不独自指出是哪一种机制。关联、家系和实验可提供不同证据，需要避免把遗传率解释成不可改变性。'],[['自然选择','可遗传差异影响繁殖成功而改变群体组成。'],['遗传漂变','有限群体中等位基因频率的随机波动。']],['虚拟p=0.7、q=0.3，平衡下杂合子比例多少？','杂合子频率2pq。','2×0.7×0.3=0.42。','42%，依赖平衡假设。'],['抗生素使细菌为适应而定向产生所需突变吗？','一般不能这样说；已有和新生变异在药物环境下被选择，部分机制需具体研究。'],['个体锻炼后肌肉增大直接等于生物进化吗？',['是','不是，进化涉及群体跨代遗传变化','所有变化都是','只需时间长'],1,'个体可塑性与群体进化是不同层次。'],['分析一个抗性演化案例','画变异、选择和传播机制，并比较漂变解释。']),
L('实验、系统与因果层次',['生命科学解释跨越分子、细胞、个体和生态层次。基因敲除、药理干预和观察关联回答不同问题；敲除改变表型可支持机制，但可能有补偿效应、脱靶和发育影响。控制组、随机化、盲法和独立重复是建立可信证据的重要条件。','系统生物学研究相互作用与反馈，不能仅把许多变量画成网络就声称因果。组学数据维度高，容易过拟合与多重检验，需要独立验证和功能实验。优秀研究报告要把描述、预测和机制区分，并明确样本、物种与实验环境的外推范围，避免从细胞结果直接跳到人体疗效。'],[['机制证据','对过程组成与干预响应的证据，不只是相关。'],['补偿效应','系统其他部分变化抵消某项干预影响。']],['虚拟细胞实验药物处理后信号下降，能否说人体疾病可治？','细胞环境与人体不同。','需检查毒性、剂量、机制、动物及临床证据。','不能直接推断人体疗效。'],['一千基因同时检验为何需多重比较控制？','即使无真实效应也会出现偶然显著，应控制错误发现并独立验证。'],['高预测准确率是否必然说明找到了因果机制？',['是','否，预测关联可能由混杂产生','只看样本量','必定无价值'],1,'预测与因果解释有不同证据要求。'],['完成生命科学研究提案','提出可干预机制、对照、重复与跨层次外推限制。'])],180);
D(54,'地球物质与能量循环怎样塑造生态，生态变化如何被测量？',['化学与能量守恒','比例和指数增长'],[53,58,60],['biology','climate'],[
L('地球圈层与循环',['地球由岩石圈、水圈、大气圈和生物圈等相互作用的系统构成。太阳能驱动许多表层过程，地球内部热驱动板块等深部过程。水、碳与营养元素在储库间迁移，储量和通量是不同量，不能把某一年度排放与长期库存直接比较而不说明单位。','生态系统包括生物群落及非生物环境，物质可以循环，能量则在转化中不断以热散失。食物网比线性食物链更接近现实，营养级能量传递效率不是固定普适常数。生态解释需要界定空间、时间与系统边界，避免把局部变化当成整个地球的结论。'],[['储库','某物质在系统组成部分中的存量。'],['通量','单位时间跨边界转移的物质量。']],['虚拟湖泊水量100万m³、年净流出20万m³，简单停留时间多少？','停留时间近似储量/流量。','100/20=5年。','约5年，假定充分混合与稳态。'],['为什么能量不能像碳一样完全循环？','能量转化遵守守恒但可用性降低并以热耗散，生态需持续外部输入。'],['年排放吨/年属于？',['储量','通量','温度','物种数'],1,'时间分母表明是流率而非存量。'],['建立本地生态系统图','标注水碳储库、通量、能量来源与人类活动。']),
L('种群、承载力与相互作用',['指数增长假设人均增长率恒定，资源限制下可用逻辑斯蒂模型dN/dt=rN(1-N/K)近似。K是特定环境下的模型参数，不是永久不变的自然上限；气候、资源和技术都可能改变它。真实种群还受年龄结构、季节、随机事件和迁移影响。','捕食、竞争、互利与寄生共同塑造群落。物种丰富度只计种数，均匀度与功能多样性提供不同信息。生态恢复不能只追求种树数量，还要检查本地物种、土壤、水文、连通性和长期存活。因果判断应结合对照、时间序列与机制，避免把同步变化都归于一种因素。'],[['承载力K','特定模型和环境下可持续种群规模参数。'],['功能多样性','生态角色和性状的差异程度。']],['虚拟r=0.2/年、N=500、K=1000，逻辑斯蒂瞬时增长多少？','1-N/K=0.5。','0.2×500×0.5=50。','50个体/年，非下一年精确净增。'],['N达到K时模型净增长为零是否说明无出生死亡？','不是，出生死亡可继续发生，只是净增长为零。'],['K能否不依环境永久固定？',['能','不能，资源与环境会变化','只依物种名字','与时间无关'],1,'K是环境依赖的近似参数。'],['比较两种生态恢复指标','用存活、连通性和物种功能检验单纯面积指标的不足。']),
L('生态韧性与管理实验',['生态韧性关注系统受扰动后能否维持或恢复关键功能，与短期稳定和不变化并不相同。正反馈可能使湖泊在清水与浑水等状态间转换，恢复条件不一定等于退化条件，这种路径差异称滞后。不能仅凭一段波动就宣称存在不可逆临界点。','管理可采用适应性方式：明确目标、竞争模型、干预、监测和调整规则。前后-对照-影响设计有助于分离干预与背景变化，但对照可比性和外部冲击仍重要。项目报告应比较生态、经济和社区影响，说明监测年限、误差与失败条件，把管理当作有责任的学习过程。'],[['生态韧性','受扰动后维持或恢复关键结构功能的能力。'],['滞后','状态转换受历史路径影响，恢复阈值与退化阈值不同。']],['虚拟治理区指标10→15，对照区12→14，净相对变化多少？','治理区+5。','对照区+2。','差中之差+3，仍需识别假设。'],['只在治理后看到鱼更多能否证明治理有效？','不能排除季节、水温或捕捞变化，需基线、对照和机制证据。'],['韧性是否等于永远不变化？',['是','不是','只等于物种数','只看瞬时产量'],1,'韧性关注扰动下功能与状态恢复。'],['设计生态管理评估','给出对照、长期监测、社区参与与调整规则。'])],160);
D(55,'怎样从直觉走向严格证明，用数学识别结构而非只套公式？',['中学代数与函数','集合符号和基本几何'],[51,61,63],['calculus','algorithms'],[
L('命题、量词与证明',['数学命题必须明确对象、条件和结论。所有与存在的量词次序会改变含义：每个人有一本喜欢的书，不等于存在同一本书被所有人喜欢。蕴含P→Q不等于逆命题Q→P，必要条件与充分条件也不能混淆。反例只需一个即可推翻全称命题，但不能靠少量例子证明它。','直接证明从假设按有效推理推出结论，反证法假设结论不成立并导出矛盾，归纳法要同时完成基础步和从任意n到n+1的推导。证明不是计算几个数观察规律，而是给所有满足条件的对象一个理由。每一步都应能说明使用了定义、已知定理还是新的假设。'],[['充分条件','P成立足以保证Q成立，但Q未必推出P。'],['反例','满足命题前提却不满足结论的对象。']],['所有素数都是奇数，如何检验？','寻找满足素数定义的偶数。','2只有1和自身两个正因子。','2是反例，命题错误。'],['x²=4是否能推出x=2？','不能，x=-2也满足；正确结论是x=±2（实数范围）。'],['验证前100项能否证明所有自然数成立？',['能','通常不能','只要图像漂亮','只需平均正确'],1,'全称结论需要普遍论证，未检查项可能反例。'],['写三种证明练习','对同一主题分别给直接证明、归纳步骤和一个错误逆命题反例。']),
L('变化率、累积与近似',['导数是差商在适当极限下的值，描述局部变化率；函数在一点可导则连续，但连续不保证可导。微积分基本定理把局部变化与整体累积联系起来，定积分可表示有符号面积或物理累积，单位取决于被积量和自变量。','近似应带误差意识。线性化f(a+h)≈f(a)+f′(a)h只在局部且曲率影响可控时可靠；数值计算还受离散步长和舍入误差影响。优化不能只找导数为零，还要检查边界、不可导点与二阶或全局条件。数学模型的正确推导不等于现实假设正确。'],[['导数','函数相对于输入的局部变化率极限。'],['定积分','连续累积的有符号总量。']],['f(x)=x²在x=3的导数与线性近似f(3.1)是多少？','f′(x)=2x，所以f′(3)=6。','f(3.1)≈9+6×0.1=9.6。','真实9.61，近似误差0.01。'],['f(x)=x²在[-1,2]最大值能只看f′=0吗？','不能，驻点0为最小；检查边界得最大值f(2)=4。'],['连续一定可导吗？',['一定','不一定，如绝对值函数在0','仅正数才可导','导数与连续无关'],1,'尖点可连续但无唯一切线斜率。'],['完成近似误差实验','比较不同步长下导数、积分或线性化误差并解释趋势。']),
L('线性结构、概率与建模',['向量空间把可加和可缩放的对象统一，线性变换保持这两种运算。矩阵表示依赖基的选择，特征向量描述变换后方向不变的非零向量。线性系统是否有解取决于秩与一致性，未知数多于方程不必然无解，可能有无穷多个解。','概率模型先明确样本空间、事件和条件。条件概率P(A|B)=P(A∩B)/P(B)不等于P(B|A)，贝叶斯公式把先验与似然结合。建模作品需同时给定义、推导、数值验证和边界条件，警惕由一个漂亮公式推导出超出数据和假设的现实结论。'],[['线性变换','保持向量加法与数乘的映射。'],['条件概率','已知条件事件发生后重新归一化的概率。']],['虚拟患病率1%、灵敏度90%、假阳性10%，阳性后患病率多少？','真阳性比例0.01×0.9=0.009。','阳性总比例0.009+0.99×0.1=0.108。','0.009/0.108≈8.33%，不能倒置条件。'],['x+y=2与2x+2y=4有几个实数解？','无限多，两方程线性相关，共同描述同一直线。'],['P(A|B)通常等于P(B|A)吗？',['总是','不是，基准率不同会改变结果','事件名字相同才可算','只看样本量'],1,'条件事件的分母不同。'],['交付一个数学建模报告','选线性系统或概率问题，提交定义、推导、检验和敏感性。'])],200);

D(56,'怎样把模糊需求变成可验证、可维护且安全的工程系统？',['数学与物理基础','流程、成本与风险概念'],[55,57,69],['physics','sre'],[
L('需求、约束与系统边界',['工程设计不是直接选一个技术方案，而是把利益相关者的需要转成可验证需求。需求说明系统应完成什么、在何种条件下达到何种指标，约束规定成本、时间、接口和安全限制。舒适、可靠等词若没有操作定义，就难以比较方案或验收。','系统边界决定哪些输入、输出和责任被纳入。把部件做到最好不保证整体最好，因为功耗、重量、速度和维护可能互相冲突。功能分解先描述必须完成的任务，再讨论实现结构，可避免过早锁定熟悉技术。可追溯矩阵连接需求、设计和验证，使遗漏与变更影响可被发现。'],[['可验证需求','具有条件、指标和检查方法的要求。'],['系统边界','划分系统内部及外部环境、接口和责任的范围。']],['虚拟要求设备续航长应怎样改写？','先给工况：每分钟采样一次、环境25℃。','再给指标与方法：满电连续运行至少24小时，以日志验证。','需求应可测试，且工况不能省略。'],['轻便且耐用为何需权衡？','减重可能改变结构裕度、材料成本与耐冲击能力，需明确量化目标和约束。'],['需求阶段最应避免？',['说明工况','用模糊形容词替代验收指标','列接口','追溯测试'],1,'无法操作化的要求难验证也易产生争议。'],['编写工程需求规格','选虚拟监测设备，列功能、环境、接口和验收要求。']),
L('方案权衡与可靠性',['方案比较可用多准则决策表，但评分、权重与尺度必须说明。某方案在每项都不差且至少一项更好时支配另一方案，否则需讨论取舍，不能假装权重是自然常数。对关键权重做敏感性分析，可检查所谓最优是否只是偏好设定的产物。','串联系统中每个部件都必须成功，独立时总可靠度为部件可靠度之积；冗余可能提高可用性，却引入共因失效、切换和维护复杂性。失效模式与影响分析逐项研究故障、后果和检测控制。风险分数只是排序辅助，低概率重大伤害仍可能需要单独控制。'],[['帕累托支配','某方案各项不劣且至少一项更优。'],['共因失效','同一原因同时破坏多个看似独立的部件。']],['虚拟独立两串联部件可靠度均0.99，系统可靠度多少？','串联要求两者都成功。','0.99×0.99=0.9801。','98.01%，低于单部件可靠度。'],['两个备用电源都接同一易断总线，算独立冗余吗？','不算，公共总线失效会同时切断，需识别共因风险。'],['加冗余总能无代价提高可靠性吗？',['能','不能，切换与共因风险也重要','只看数量','维护无关'],1,'冗余收益依赖独立性、控制和维修。'],['做方案权衡与失效表','比较三方案，列五种失效及重大风险控制。']),
L('验证、确认与生命周期',['验证问设计是否符合规格，确认问做出的系统是否真正满足使用需要。实验室通过全部测试仍可能在真实环境难用，因此既要需求测试，也要场景验证。测试应覆盖正常、边界、异常与退化状态，记录版本、仪器、输入和判定标准，避免凭印象验收。','生命周期工程考虑生产、部署、维修、升级和退役，前期便宜可能带来高维护与环境成本。变更控制需评估接口、风险与已有证据是否仍有效。优秀课程设计不仅交原型，还应交需求追溯、验证记录、故障处理和维护计划，让别人能够复现并安全接手系统。'],[['验证','检查实现是否满足已规定要求。'],['确认','检查系统是否满足实际使用目的和用户需要。']],['虚拟传感器精度合格但安装后无法更换电池，问题是什么？','精度测试只覆盖一项规格。','维护与实际使用需求未充分确认。','需补可维护性需求并重新评估结构。'],['更换关键材料后旧测试能否全部沿用？','不能自动沿用，应做变更影响分析并重测受影响的强度、寿命和安全项。'],['符合规格是否必然满足真实需要？',['必然','不必然，规格可能遗漏或错误','无需用户','只要有报告'],1,'验证与确认回答不同问题。'],['交付系统设计档案','包括需求、权衡、原型、测试、维护和退役安排。'])],180);
D(57,'材料的微观结构怎样决定性能，纳米尺度为何既有机会也有限制？',['化学键与原子结构','应力、应变和能量'],[52,56,70],['materials','chemistry'],[
L('结构、缺陷与性能',['材料科学把加工、结构、性质与性能联系起来。相同化学成分可能因晶粒、相分布、孔隙和缺陷产生不同表现，因此不能只凭元素组成判断强度或导电性。晶体具有周期排列，非晶材料缺少长程周期，真实材料都存在缺陷，缺陷并不总是坏事。','应力是单位面积受力，应变是相对形变，在线性弹性范围内二者比值为弹性模量。强度、刚度、韧性和硬度不同：高刚度不保证抗断裂，高硬度也不保证冲击韧性。选材需匹配载荷、温度、腐蚀和加工条件，不能用单一排行榜决定所有工程用途。'],[['弹性模量','线性弹性范围内应力与应变的比。'],['韧性','吸收能量并抵抗断裂的能力，不能与硬度混同。']],['虚拟截面积10mm²承受1000N，应力多少？','σ=F/A。','1000/10=100N/mm²。','100MPa，1N/mm²=1MPa。'],['弹性模量高是否说明材料一定难断？','否，刚度与断裂韧性不同，脆性高模量材料也可能易断。'],['同成分材料性能是否必定相同？',['相同','不同加工微结构可改变性能','只看颜色','缺陷无影响'],1,'微结构和缺陷是性能的重要决定因素。'],['做选材性能矩阵','比较金属、陶瓷、聚合物的目标性能与失效风险。']),
L('相图、扩散与强化',['相图描述平衡条件下温度、成分与相组成的关系，实际加工能否接近平衡取决于时间与扩散。杠杆定则按两相端点成分和总成分求相比例，不能把相图直接当作所有冷却过程的动态图。快速冷却可能形成亚稳结构，随后时效又会改变性能。','扩散是粒子热运动产生的净迁移，浓度梯度可驱动通量；温度通常强烈影响扩散速率。强化可以通过晶粒细化、固溶、析出或加工硬化阻碍位错运动，但常需与延性、导电性和高温稳定性权衡。解释要指出具体微观机制，而不是简单说越硬越先进。'],[['扩散','热运动导致粒子迁移并产生宏观混合或输运。'],['位错','晶体中的线缺陷，其运动与塑性变形有关。']],['虚拟两相端点20%和80%，总成分50%，两相比例多少？','低成分相份额=(80-50)/(80-20)。','结果30/60=0.5，另一相亦0.5。','各50%，假定平衡且比例口径一致。'],['为什么快速冷却结果可能不同于平衡相图预测？','扩散来不及完成，形成非平衡或亚稳组织。'],['强化是否总能同时提高延性？',['总能','不一定，常有性能权衡','完全无关','只看价格'],1,'阻碍塑性变形的机制可能降低延展能力。'],['解释热处理路径','用公开或虚拟相图说明组织、时间尺度与性能变化。']),
L('纳米尺度与表征证据',['尺度变小时表面积与体积之比增加，表面能、界面与量子限域可能更显著，但并非任何纳米材料都自动优越。球体比表面积与1/r成正比，分散、团聚和表面化学决定实际可用界面。实验还要检查样品是否真的达到声称的尺寸与结构。','显微成像给局部结构，衍射反映平均有序性，光谱提供化学和电子信息，各方法都有分辨率、取样与制样局限。少量漂亮图像不能代表批量均一性。纳米工程还需考虑毒理、暴露、回收和规模化成本，毕业作品应将性能提升与对照、重复和生命周期风险一起报告。'],[['比表面积','单位质量或体积的表面面积。'],['表征互证','用不同物理原理的方法检验结构与组成解释。']],['同材球半径减为原来1/10，比表面积约变几倍？','球A/V=3/r。','半径缩小10倍，比值增大10倍。','约10倍，前提无团聚且表面可接近。'],['一张电镜图能否证明整批样品均为10nm？','不能，需要代表性取样、尺寸分布和其他表征，检查制样偏差。'],['纳米尺度性能提升是否普遍无风险？',['是','否，需具体结构、暴露和成本证据','只看宣传','越小必越好'],1,'表面与量子效应既带机会也有稳定性和健康风险。'],['完成纳米材料证据审查','比较尺寸分布、对照性能、重复性、团聚与暴露风险。'])],180);
D(58,'怎样核算能源数量与品质，评价低碳方案的系统代价？',['能量、功率与单位','百分比和现金流'],[51,54,60],['physics','climate'],[
L('能量、功率与效率',['能量表示可转移和转化的量，功率是单位时间能量流，1kWh等于3.6MJ。装机功率不能直接当年发电量，还需运行时间、容量因子、停机与资源条件。效率是有用输出与输入能量之比，必须说明何为有用、系统边界在哪。','能量守恒不代表所有能量具有相同做功能力。热机受冷热端温度约束，理想卡诺效率为1-T冷/T热，温度用开尔文。实际系统存在摩擦、传热温差和其他不可逆损失，因此低温余热不能等量当作高品位电能，能源比较需同时考虑数量和品质。'],[['功率','单位时间的能量转移或转化速率。'],['容量因子','实际期间发电量与满功率连续运行理论量之比。']],['虚拟1kW设备连续运行3小时，用电多少？','能量=功率×时间。','1×3=3kWh。','3kWh=10.8MJ。'],['热端600K、冷端300K，理想热机最高效率多少？','1-300/600=50%，实际效率通常更低。'],['1MW装机是否等于每年1MWh发电？',['等于','不等，功率与能量不同','只看名字','容量因子无关'],1,'年发电量还需小时数与运行比例。'],['建立家庭能源单位表','用虚拟电器负荷换算功率、能量与峰值需求。']),
L('可再生能源与储能系统',['风光发电受天气与昼夜影响，单个设备的平均成本无法代表电力系统成本。电网需随时平衡供需，依靠跨区连接、需求响应、灵活电源和储能组合。储能功率决定能多快充放，容量决定能持续多久，两者不能只用一个电池大小指标混淆。','电池往返效率低于100%，储存会损耗能量，还受寿命、温度和循环深度影响。平准化度电成本把全寿命成本与发电量折现比较，但对不同价值时段、可靠性和系统整合差异不充分。比较应明确服务功能：提供电量、峰值功率还是长时备用。'],[['储能时长','可用能量容量除以放电功率的近似时长。'],['系统整合成本','为满足整体电力可靠性而产生的额外配置与运行成本。']],['虚拟电池容量8MWh、功率2MW，满功率能放多久？','时长=8/2。','忽略损耗与容量限制为4小时。','约4小时，实际需用可用容量与效率。'],['充电10MWh，往返效率80%，可回送多少？','8MWh；未计额外运行约束。'],['最低单机度电成本是否必然是最低系统成本？',['必然','不一定，服务时段与可靠性不同','只看装机','不需要电网'],1,'电力价值取决于时间、位置和可调度性。'],['比较两种供电组合','用虚拟逐时负荷检验风光、储能与备用是否满足需求。']),
L('生命周期与转型路径',['能源方案的环境评价应覆盖开采、制造、运输、运行和退役，选择一致功能单位，例如每kWh交付电力。运行零排放不等于全生命周期零排放，但也不能用制造排放否定所有运行减排；需要在相同边界、寿命和电网条件下计算。','转型路径同时涉及技术、资金、基础设施、矿产和分配。边际减排成本可比较每减少一吨排放的净成本，但忽略协同效益、公平和基础设施依赖时会误导。优秀报告应提供基准、替代情景、敏感性与受影响群体，区分工程可行、经济可行和政治实施难度。'],[['生命周期评价','按明示边界核算产品全阶段环境影响。'],['功能单位','比较方案时统一的服务输出量。']],['虚拟设备制造排放1000kg，每年相对基准减排500kg，简单碳回收期多久？','1000/500=2。','需确认减排为净差值且年服务相同。','约2年，不含退役及未来电网变化。'],['比较电动车和燃油车为何要统一里程与寿命？','它们提供的是交通服务；不统一功能会把使用量差异误当技术差异。'],['运行零排放等于？',['全生命周期必零','仅运行阶段该边界下为零','制造不消耗资源','无需核算'],1,'边界必须包括实际比较目的所需阶段。'],['提交能源转型评估','统一服务需求，比较成本、可靠性、生命周期与公平。'])],160);
D(59,'怎样从分子机制走到可靠临床证据，避免把希望当疗效？',['生物学与基础化学','概率、基准率和对照'],[53,63,91],['biology','who'],[
L('靶点、剂量与人体系统',['药物可能通过受体、酶或其他靶点改变生物过程，但靶点结合不等于患者获益。人体存在吸收、分布、代谢和排泄，血药浓度与给药量并非一回事。剂量与效应可能饱和，副作用和治疗窗口限制可用范围，本课程只解释机制，不提供个人用药或诊疗方案。','免疫系统区分并响应威胁，先天与适应性过程协作。疫苗通过适当抗原刺激形成保护相关免疫记忆，但具体保护程度、持续时间和风险依产品及人群而异。不能把增强免疫力当万能目标，过度或错误免疫反应也会造成伤害。'],[['药代动力学','研究药物在体内浓度随时间变化的过程。'],['治疗窗口','有效与不可接受毒性暴露之间的范围。']],['虚拟体内药量100单位，按固定半衰期经过两次半衰期剩多少？','一次剩50。','第二次剩25。','25单位，假定一阶消除且无新增给药。'],['细胞中结合靶点是否证明临床有效？','否，还需暴露、选择性、安全和患者相关终点等证据。'],['药物剂量翻倍效果总翻倍吗？',['总是','不一定，可能饱和且毒性改变','只看价格','人体没有代谢'],1,'剂量、浓度、靶点占据和临床结果是不同环节。'],['画药物证据链','从靶点到暴露、安全、临床终点逐项列证据缺口。']),
L('临床试验与绝对风险',['随机对照试验通过分配减少混杂，盲法减少期望和测量偏差。临床终点直接关联患者感受、功能或生存，替代终点如某个生物标志物未必充分代表它们。统计显著不等于临床重要，样本量很大时微小差异也可能显著。','相对风险降低与绝对风险降低必须区分。基准事件率越低，同样相对降低对应的绝对收益越小。治疗获益还应与不良反应、时间、成本和人群适用性比较。研究报告应标明随机、对照、失访、分析集和不确定区间，不能仅摘取最有利的一个百分数。'],[['绝对风险降低','对照事件率减干预事件率。'],['替代终点','代替患者直接重要结果而测量的中间指标。']],['虚拟试验事件率对照10%、干预8%，相对和绝对降低多少？','绝对差10%-8%=2个百分点。','相对降低2/10=20%。','绝对2个百分点，相对20%，不能混写。'],['若绝对风险降低0.02，简化NNT多少？','1/0.02=50，需注明随访时间和人群，不能作为个人建议。'],['统计显著意味着临床重要吗？',['意味着','不一定','意味着无副作用','意味着适合所有人'],1,'效应大小、精度和实际价值需分别判断。'],['读一份试验摘要','提取PICO、绝对效应、不良反应与失访，核查结论是否越界。']),
L('诊断评估与转化边界',['诊断灵敏度是患病者检测阳性的比例，特异度是无病者检测阴性的比例；阳性预测值还依赖患病基准率。低患病人群中即使较好的检测也可能有许多假阳性，因此筛查价值需看后续确诊、过度诊断、伤害和可实施干预，而不只看准确率。','转化研究从实验室走向真实医疗，需要不同阶段的安全与效果验证。算法在单中心数据上表现好不等于跨医院可靠，设备、流程和人群变化会导致分布漂移。优秀评估应包含独立验证、伦理与数据治理、临床工作流和持续监测，课程作品不能冒充医疗器械或诊断服务。'],[['阳性预测值','检测阳性者中真正患病者的比例。'],['分布漂移','应用人群或数据机制与开发阶段不同。']],['虚拟10000人患病率1%，灵敏90%、特异90%，阳性中真病多少比例？','真阳性90，假阳性990。','阳性共1080。','90/1080≈8.33%，展示基准率影响。'],['只在训练医院验证的模型能直接用于所有医院吗？','不能，需跨机构独立验证、校准和临床影响评估。'],['灵敏度90%是否等于阳性后患病90%？',['等于','不等，条件方向与基准率不同','只看样本数','任何时候都等于'],1,'P(阳性|患病)与P(患病|阳性)不是同一量。'],['完成健康科技证据审查','评估一个虚拟诊断工具的基准率、验证、伤害与治理，不做个人诊断。'])],180);
D(60,'怎样用物理、生态与政策证据共同理解污染和气候治理？',['能量与碳循环','概率、图表和经济外部性'],[54,58,50],['climate','economics'],[
L('天气、气候与温室机制',['天气是短期状态，气候描述长期分布、均值、变率与极端，某地某天寒冷不能独自反驳全球长期变暖。温室气体吸收并发射部分地球长波辐射，改变能量收支；地表温度变化还涉及反馈、海洋热吸收和气溶胶等作用，不能只用单一局部温度图判断。','环境问题需区分排放、环境浓度、暴露和健康或生态结果。相同排放在不同气象、地形和人口位置下可造成不同暴露。统计趋势应标明时间、空间、基准和数据处理，短序列容易受自然变率影响。观测与物理机制共同支持判断，单个相关图不构成完整归因。'],[['气候','长期天气统计分布，包括均值和极端。'],['暴露','人或生态对象接触污染物的程度与时间。']],['虚拟某城一天降温10℃能否说明全球多年趋势逆转？','时空尺度不同。','需要全球长期观测而非单日局部值。','不能据此推翻长期趋势。'],['同样排放量是否必然产生同样健康风险？','不必然，扩散、暴露人口、持续时间和脆弱性不同。'],['天气与气候最关键区别？',['有没有云','时间尺度与统计含义','是否在城市','只看温度单位'],1,'气候是长期分布而非某次天气。'],['制作环境因果链','把来源、排放、浓度、暴露和影响分开并标出测量方法。']),
L('碳预算、反馈与不确定性',['二氧化碳是累积性问题，年度排放减少不等于大气浓度立即下降，还取决于陆地和海洋吸收。碳预算把目标温升与一定概率和假设下的累计净排放联系起来，不是对所有温室气体和未来路径完全确定的固定数字。净零二氧化碳与所有温室气体净零也应区分。','反馈会增强或减弱初始变化，例如水汽、冰雪反照率与碳循环响应。气候模型用物理规律和参数化描述系统，情景表示可能排放路径，不是自动预测人类选择。报告不确定性不能等同于什么都不知道；应说明哪些机制稳健、哪些范围仍依模型和情景而变。'],[['累计排放','跨时间积分后的排放总量。'],['情景','关于未来驱动与选择的条件性路径，不等于预测。']],['虚拟年排放从100降到80但仍为正，累计排放怎样？','每年仍增加净排放。','下降的是增加速度，不是累计存量。','累计仍上升，需另考虑净吸收。'],['为什么不能把排放下降20%写成大气浓度下降20%？','排放是流量，浓度与累积、吸收和循环有关，非一一同比。'],['存在不确定性意味着无需行动吗？',['意味着','不意味着，应结合风险与稳健决策','意味着规律不存在','只看一个模型'],1,'风险管理本就面对范围与概率，而非等待完全确定。'],['比较三条排放路径','计算虚拟累计排放并解释净零时点与路径依赖。']),
L('外部性、政策组合与公平',['污染外部性使私人决策未承担全部社会成本。碳税通过价格激励减排，排放交易通过总量与许可市场分配；具体效果依覆盖、执行、价格稳定和替代技术。两者不自动解决信息、创新、基础设施和分配障碍，往往需标准、投资与社会保障组合。','减缓减少变化来源，适应降低既定变化的损害，两者互补但不能无限替代。治理评估需讨论谁排放、谁受害、谁支付与谁获益，避免把平均净收益掩盖的损失忽略。优秀方案应有基准、反事实、成本、执行和公平指标，并检查跨地区转移及碳泄漏。'],[['碳泄漏','一地政策使排放活动转移到其他地区。'],['适应','降低气候变化暴露与脆弱性的调整措施。']],['虚拟碳价100元/吨，方案每减一吨成本60元，企业激励如何？','不减排需付100。','减排成本60可避免100。','在简化条件下减排有40元/吨净激励。'],['建防洪设施是否可完全替代减排？','不能，适应有成本和极限，持续变化仍会增加风险，需互补。'],['评价碳政策应只看总减排吗？',['应','不应，还需成本、执行与分配','只看口号','无需反事实'],1,'社会可持续性依赖效果与公平共同评估。'],['提交气候政策备忘录','比较价格、标准、投资和补偿组合，明确受影响群体。'])],180);
D(61,'计算机如何表示和执行信息，算法何以正确且高效？',['离散数学、逻辑与集合','基本代数及二进制'],[55,62,69],['cs50','algorithms'],[
L('表示、状态与程序执行',['计算机用位表示信息，位模式的意义取决于编码与类型，同样的位可以被解释为整数、字符或指令。固定宽度整数有范围，浮点数只能近似表示许多实数，因此数学等式在程序中可能受溢出和舍入影响。抽象隐藏实现细节，但不能消除资源与精度限制。','程序执行可理解为状态随指令变化，变量、控制流、函数和内存共同构成过程。递归需要基础情形与朝基础情形前进的规则，否则无法终止。学习时应手工追踪输入、状态和输出，再用测试检查边界；能运行一次不等于对所有输入都正确。'],[['编码','位模式与符号或数值之间的约定映射。'],['状态','某一执行时刻变量与存储等信息的集合。']],['8位无符号整数最大值多少？','共有2⁸=256种位模式。','从0起编号到255。','255；有符号类型范围不同。'],['为何0.1+0.2在部分语言不精确等于0.3？','二进制浮点不能精确表示这些十进制小数，运算与比较需考虑误差。'],['同一位模式含义由什么决定？',['位本身自动决定','编码与类型上下文','屏幕颜色','文件大小唯一决定'],1,'表示规则赋予位模式语义。'],['实现并追踪小程序','完成整数转换、循环与递归，记录边界和状态变化。']),
L('数据结构与复杂度',['算法正确性与效率是不同问题。时间复杂度研究输入规模增长时操作量的阶，O记号给渐近上界而不是具体运行秒数；同为O(n)也可能有不同常数。分析要明确最坏、平均或摊还情形，以及输入与计算模型。','数组提供按索引访问，链表依靠链接遍历，哈希表常见平均常数查找依赖散列和负载假设，最坏可能退化。二分查找要求有序并维护候选区间，循环不变式可证明每轮不丢目标。选结构要匹配插入、删除、遍历和内存需求，不能把某一种结构当万能最快。'],[['渐近复杂度','输入规模增大时资源需求增长阶的描述。'],['循环不变式','每次迭代前后持续成立并支持正确性的性质。']],['有序1024项二分查找约需多少次折半？','1024=2¹⁰。','每步候选区间约减半。','约10轮定位尺度，精确比较数依实现定义。'],['哈希表查找平均O(1)是否保证每次恒定耗时？','不保证，冲突、扩容和恶劣输入可改变单次及最坏表现。'],['O(n)直接表示多少秒吗？',['表示n秒','不表示，是增长上界阶','表示所有机器相同','只描述内存'],1,'耗时还依常数、硬件和输入。'],['比较两种查找结构','实现线性、二分或哈希查找，报告前提、正确性和规模实验。']),
L('可计算性、图与系统权衡',['图用顶点和边表示关系，广度优先搜索在无权图中按层扩展，可得边数最少路径；带权图则需符合权重条件的算法。动态规划适用于具有可复用子问题和合适最优子结构的问题，应说明状态、转移、边界和计算顺序，不能只背某段代码。','可计算性问是否存在算法，复杂性问资源需要多少，二者不可混淆。停机问题不存在适用于所有程序输入的通用判定算法，这不意味着具体程序都无法分析。优秀本科作品要同时给规范、证明、复杂度和实验，并说明输入限制、内存与实际系统行为造成的差距。'],[['广度优先搜索','按与起点的边数距离逐层探索图。'],['可计算性','问题是否存在能对所有合法输入终止并正确求解的算法。']],['无权图A-B-C与A-D-C，BFS从A到C最短距离？','A为第0层，B、D为第1层。','C在第2层首次到达。','距离2条边，两条路径均最短。'],['有负权边时能无条件使用Dijkstra吗？','不能，经典正确性依赖非负权；需选适当算法并检查负环。'],['不可计算等于运行太慢吗？',['等于','不等，一个问存在性一个问资源','只差电脑价格','只看数据量'],1,'资源再大也不能解决一般不可计算性。'],['完成算法课程项目','求解一项图或动态规划任务，提交证明、测试和性能分析。'])],240);
D(62,'机器学习如何从数据学出预测，何时会过拟合或失去可靠性？',['线性代数、概率与微积分','Python和数据表操作'],[61,63,55],['ml','deep'],[
L('监督学习与损失函数',['监督学习用带标签样本学习输入到输出的映射，回归预测数值，分类预测类别或其概率。训练通过最小化损失调整参数，损失选择表达了错误的代价；均方误差对大残差更敏感，分类准确率在严重不平衡时可能误导。预测目标必须对应实际决策需求。','训练误差低不等于泛化好。模型可能记住噪声或利用泄漏信息，因此需把训练、验证和最终测试分开。测试集不应被反复用于调参。基线模型帮助判断复杂模型是否真正改善；数据质量、抽样和标签机制往往比模型名字更重要。'],[['损失函数','把预测与目标差异映射为优化代价的规则。'],['泛化','模型在未用于拟合的数据上的表现。']],['虚拟预测[2,4]，真实[1,5]，均方误差多少？','残差分别1和-1。','平方平均(1+1)/2=1。','MSE=1，单位是目标单位的平方。'],['99%样本为负，全部预测负准确率多少，为何不足？','99%；但正类召回为0，无法证明能识别重要正类。'],['训练误差越低必然越好吗？',['必然','不必然，可能过拟合','测试无需保留','模型越大永远最好'],1,'应评价独立数据上的目标相关效果。'],['建立预测基线','用公开教学数据比较常数预测与线性模型，固定数据切分。']),
L('正则化、优化与评估',['过拟合来自模型对训练数据特有波动的适应，正则化通过限制参数或增加惩罚降低某些复杂性。偏差与方差提供解释视角，但并不保证所有现代模型都遵循简单曲线。交叉验证在数据独立同分布等条件下估计表现，时间或分组数据应按结构切分，防止近重复泄漏。','梯度下降按损失对参数的导数更新，学习率过大可能发散，过小可能收敛慢。训练前的标准化也必须仅用训练集估计参数。分类评估应结合精确率、召回、阈值、校准和误判成本，不能用一个AUC代替所有部署需求。'],[['正则化','以约束或惩罚控制拟合复杂性的方法。'],['数据泄漏','建模使用了部署时无法获得或跨切分泄露的信息。']],['虚拟参数w=2，梯度3，学习率0.1，一步梯度下降后多少？','更新w新=w旧-ηg。','2-0.1×3=1.7。','1.7，假定最小化目标。'],['同一患者多条记录随机分到训练测试有何风险？','个体特征泄漏使测试过于容易，应按患者分组切分并匹配应用场景。'],['标准化均值应从哪里估计？',['全数据含测试','只用训练部分','未来部署结果','随意指定后宣称优化'],1,'测试信息不应进入训练处理流程。'],['完成可复现模型比较','固定分组或时间切分，比较正则、阈值、校准与误差群体。']),
L('深度网络、分布漂移与治理',['神经网络通过多层可学习变换表示复杂函数，反向传播利用链式法则计算梯度；训练大模型并不自动赋予因果理解。模型可利用背景、标注或采样捷径，在训练环境好而换环境失败。解释方法显示部分相关敏感性，不能直接当成完整机制证明。','部署前要评估分布漂移、群体差异、隐私、安全和失效处理。人类复核若缺时间、权限和信息可能只是形式。模型卡应说明用途、数据、限制、评估与禁止外推场景。生成内容要核实引用和事实，概率上流畅的输出并不保证真实；毕业作品应有监测、回退与独立验证。'],[['反向传播','用链式法则高效计算网络参数梯度。'],['捷径学习','利用训练数据中非目标机制线索取得表面高表现。']],['虚拟猫狗分类训练图中狗总带水印，测试去掉水印后失效说明什么？','水印与标签在训练中相关。','模型可能使用水印捷径而非形态。','需干预线索、独立数据和错误分析验证。'],['给模型增加人类审核就保证安全吗？','不能，需检验审核者能力、时间、自动化偏见、权限和失误处理。'],['生成模型给出论文标题就代表论文存在吗？',['代表','不代表，需查原始来源','语气坚定即代表','参数多就代表'],1,'模型可能生成格式合理但不存在的引用。'],['交付负责任学习系统','提交数据与模型说明、切分、错误分析、漂移监测与回退策略。'])],240);
D(63,'怎样从数据得到可信结论，并区分描述、预测与因果？',['概率、统计与线性代数','表格与基本编程'],[55,62,37],['statistics','ml'],[
L('数据生成、抽样与清洗',['数据不是现实本身，而是由测量、记录、筛选和制度产生的观测。首先明确研究单位、变量定义、时间与抽样框。便利样本可能漏掉未联网、未购买或未响应的人，样本再大也不能自动消除选择偏差。缺失可能与结果相关，直接删行会改变研究对象。','清洗要保存原始数据与变更记录，处理重复、单位、异常和编码时依据机制而非只追求整齐。离群值可能是录入错误，也可能是真实重要事件。描述统计同时报告分布、中心与离散，均值可能被极端值拉动，中位数也会掩盖尾部风险。'],[['抽样框','研究中可能被抽到的单位清单或机制。'],['缺失机制','数据为何缺失以及与观测、未观测变量的关系。']],['虚拟收入1、2、3、4、100，均值和中位数多少？','均值110/5=22。','排序中间值3。','均值22，中位数3，揭示右偏分布。'],['只调查购买者能否推断所有访客为何不购买？','不能，未购买者不在样本中，需补抽样并明确目标人群。'],['大样本能自动消除选择偏差吗？',['能','不能','只要超过一万','只看均值'],1,'扩大有偏抽样可精确估计错误人群。'],['建立数据字典与清洗日志','用公开教学数据说明单位、缺失、重复和每项处理理由。']),
L('估计、区间与检验',['样本统计量用于估计总体参数，标准误描述估计因抽样而变动的程度，不等于原始数据标准差。频率学95%置信区间的解释是重复使用该方法时约95%的区间覆盖固定真值，不是任意给当前真值赋95%概率。模型假设和抽样机制决定区间可信度。','p值是在零假设及模型条件下观察到至少如此极端数据的概率，不是零假设为真的概率，也不是效应大小。显著结果可能来自大样本或多重比较，不显著可能精度不足。应同时报告估计值、区间、研究设计与实际意义，避免只用星号决定结论。'],[['标准误','估计量在抽样机制下变动程度的度量。'],['p值','零假设与模型成立时数据至少如此极端的概率。']],['虚拟独立样本标准差10、n=100，均值标准误多少？','SE=s/√n。','10/10=1。','约1，依赖独立抽样等条件。'],['p=0.03能否说零假设只有3%概率为真？','不能，这是倒置条件概率，p值不是假设后验概率。'],['标准差与标准误相同吗？',['相同','不同，一个描述数据一个描述估计变异','只差单位','样本大时永远相同'],1,'均值标准误通常随样本量增长而下降。'],['完成估计报告','对一个参数报告估计、区间、设计与实际意义，解释未满足假设。']),
L('因果识别与数据产品',['预测模型拟合P(Y|X)，因果分析关注干预X会怎样改变Y，二者不相同。混杂变量同时影响处理和结果，控制更多变量不总更好，控制碰撞点或处理后的中介可能引入偏差。因果图应依据领域机制而非只依据相关系数自动画出。','数据产品还需管理可复现、隐私、版本与监测。一次分析结果可能随数据更新和口径变化，管道应保留输入、代码、环境与质量检查。大数据系统增加吞吐不自动提高测量有效性。优秀项目应明确描述、预测或因果目标，选择匹配方法，并允许别人复算关键结果。'],[['混杂','共同原因使处理与结果产生非因果关联。'],['可复现管道','能从明示输入与版本重新生成结果的流程。']],['虚拟冰淇淋销量与溺水同升，可说冰淇淋导致溺水吗？','天气炎热可能同时增加两者。','存在共同原因混杂。','相关不能直接支持吃冰淇淋的因果效应。'],['回归控制所有可得变量是否必然减少偏差？','不必然，碰撞点、处理后变量与测量误差可能引入偏差。'],['数据量增加直接保证什么？',['因果识别','都不保证，质量与设计仍关键','无选择偏差','隐私安全'],1,'计算规模不能替代有效测量与识别。'],['交付数据科学项目','提交数据字典、管道、验证、解释及隐私与因果边界。'])],220);
D(64,'怎样围绕资产与威胁建立防护，而不把安全当工具清单？',['网络、操作系统和Web基础','基本编程与权限概念'],[61,65,69],['owasp','mdn'],[
L('资产、威胁与最小权限',['信息安全常以机密性、完整性和可用性组织目标，三者可能有冲突。威胁建模先确定资产、攻击者能力、信任边界和可能失败路径，再选择控制。漏洞是弱点，威胁是可能利用它的来源或事件，风险还取决于发生可能性和后果，不能把三个词混用。','最小权限让账户和服务只拥有完成任务需要的访问能力，减少被攻破后的影响。身份认证确认是谁，授权决定能做什么，前端隐藏按钮不能替代服务器权限检查。课程实验只在自有或明确授权的隔离环境进行，学习目标是防御与可验证修复而不是攻击他人系统。'],[['认证','验证身份或凭据的过程。'],['授权','依据身份与规则决定是否允许某项操作。']],['虚拟网页隐藏管理按钮但API未检查权限，安全吗？','用户仍可能直接发API请求。','服务器需验证每次敏感操作的身份和权限。','不安全，界面隐藏不是授权边界。'],['备份最直接支持安全三目标中哪项？','主要支持可用性与恢复，也需保护备份机密性和完整性。'],['登录成功是否代表能访问所有资源？',['代表','不代表，还需授权','只看页面','权限只在前端'],1,'认证与授权是不同控制。'],['画一个应用威胁模型','列资产、边界、角色、三条失败路径与防御验证。']),
L('哈希、加密与输入安全',['哈希把任意长度输入映射到固定长度摘要，密码学哈希追求单向和抗碰撞等性质，但它不是可解密的加密。密码存储应使用专门的慢速带盐口令哈希方案，不应仅对明文做一次快速摘要。加密保护机密性，密钥管理、完整性和访问控制仍不可缺。','注入问题来自把不可信输入混入可执行语义。参数化查询把数据与SQL结构分离，输出编码则按HTML、属性或脚本等上下文防止内容变代码；二者不能互相替代。所有外部输入应按用途验证，错误信息和日志也要避免泄露秘密。'],[['带盐口令哈希','加入每条独立随机盐并用专用算法增加离线猜测成本。'],['参数化查询','通过数据库参数接口将输入作为数据而非SQL语法。']],['虚拟用户输入姓名含引号，怎样安全查数据库？','不拼接SQL字符串。','使用占位符并把姓名作为独立参数绑定。','数据与语法分离，同时按业务验证输入。'],['把密码Base64编码后存储安全吗？','不安全，Base64是可逆编码，不是口令保护或加密。'],['哈希是否通常能用密钥解密回原文？',['能','不能，它不是可逆加密','只要摘要长就能','Base64等于哈希'],1,'编码、哈希和加密承担不同任务。'],['完成安全输入练习','在隔离教学应用中实现参数化、上下文编码和密码处理说明。']),
L('纵深防御、检测与响应',['安全设计应假设某层控制可能失效，结合权限分离、补丁、秘密管理、网络边界、监控和恢复形成纵深防御。多因素认证降低部分凭据风险，但仍需防钓鱼、会话劫持和恢复流程薄弱。威胁清单是起点，不能替代业务特定资产与攻击路径分析。','事故响应需准备、检测、遏制、清除、恢复和复盘，保护证据并明确沟通责任。日志应可关联时间与事件，同时最小化敏感信息。恢复不能只看服务启动，还要核实数据完整性、权限和持续入侵。优秀安全报告说明复现条件、影响、修复与回归验证，避免公开可滥用秘密。'],[['纵深防御','多个相互补充控制降低单点失效影响。'],['恢复演练','实际验证备份、流程与权限能达到恢复目标。']],['虚拟有每日备份但从未恢复测试，能保证恢复吗？','备份可能损坏、缺密钥或缺依赖。','需隔离恢复并核对数据和时间目标。','不能仅凭备份任务成功宣称可恢复。'],['安全日志应记录用户明文密码便于排查吗？','不应，泄露会扩大风险；记录必要事件和脱敏标识，保护访问。'],['发现入侵后第一步是否总是立即删全部日志？',['是','否，应保护证据并按响应方案遏制','日志无用','只需改网页'],1,'销毁证据会妨碍调查与确认清除。'],['交付防御与响应方案','包含威胁模型、修复证明、日志最小化和恢复演练。'])],200);
D(65,'云服务如何组合计算与存储，分布式故障怎样改变设计？',['网络、操作系统和数据库基础','概率、延迟与吞吐'],[61,64,69],['cloud','sre'],[
L('云服务模型与共享责任',['云计算强调按需自助、网络访问、资源池、弹性和可计量服务。IaaS提供基础计算网络资源，PaaS提供应用运行平台，SaaS提供完整应用，实际服务边界可混合。迁到云不代表运维责任消失，用户仍需按服务模型管理身份、数据、配置和应用安全。','虚拟机抽象硬件，容器共享宿主内核并隔离进程环境，二者隔离与部署特性不同。弹性扩缩能调整容量，但启动、数据迁移和配额存在延迟。成本不仅是CPU小时，还包括存储、请求、带宽、闲置和人员，比较方案应基于同一工作负载与可靠性目标。'],[['共享责任','提供商与使用者按服务边界分担安全和运维职责。'],['弹性','按负载需求调整资源的能力，并非无限即时。']],['虚拟SaaS用户误把文档设公开，能说全由云商负责吗？','云商负责其服务平台部分。','用户共享配置和数据治理仍属用户责任。','需按合同与服务边界分析，不能概括甩责。'],['容器与虚拟机的关键区别之一是什么？','容器通常共享宿主内核，虚拟机有各自客体系统与硬件虚拟化边界。'],['上云意味着无需备份和权限管理吗？',['意味着','不意味着','只要付费即可','SaaS无数据责任'],1,'服务交付不取消客户侧配置与治理。'],['画云系统责任图','为虚拟服务标出各层责任、数据与费用来源。']),
L('复制、一致性与幂等',['分布式系统节点可独立故障，网络消息可能延迟、丢失或重复，无法把远端调用当成本地函数。复制提高可用性或读取能力，却引入副本一致性问题。网络分区时，系统对一致性和每次请求及时响应的取舍必须明确，CAP不能简化成任何时候随便选三项中的两项。','重试可能使同一业务操作执行多次，幂等设计让重复请求产生与一次相同的业务效果。支付或订单可使用唯一操作键与原子状态转移，不能只靠客户端认为发了一次。消息队列的投递语义与最终业务效果不同，所谓恰好一次需要限定端到端边界。'],[['幂等','重复同一操作不会继续改变预期业务结果。'],['网络分区','部分节点间无法按正常方式通信的故障状态。']],['虚拟付款超时后重试，为何可能重复扣款？','超时只表示客户端没收到结果。','服务端第一次可能已完成。','需幂等键和服务端状态核验，不能把超时当未执行。'],['所有副本都立即确认写入，对延迟和故障有何影响？','可能提高特定一致性保证，但延迟增大且部分节点不可达时可能阻塞。'],['超时必然等于操作没发生吗？',['必然','不必然','只有GET超时','网络不重复'],1,'远端已执行但响应丢失是常见不确定状态。'],['实现幂等业务模拟','用虚拟重复消息测试订单状态和去重边界。']),
L('SLO、错误预算与故障演练',['服务水平指标SLI测量用户相关行为，例如请求成功率或延迟分位数，SLO设定其目标，SLA则可能带合同义务。平均延迟会掩盖慢请求，应根据体验关注尾部。错误预算是目标允许的不可靠程度，用于平衡发布速度与稳定性，而不是允许随意制造事故。','可靠性需要容量规划、过载保护、超时、退避、限流、降级与恢复。重试风暴可放大故障，应控制预算和随机退避。故障演练先明确范围、停止条件与恢复措施，观察检测和协作而非追求破坏。课程项目应包含监控、数据完整性、备份恢复和复盘，说明系统何时选择拒绝请求。'],[['SLO','对用户相关服务指标设定的可靠性目标。'],['错误预算','目标允许的失败量或不可靠时间额度。']],['虚拟100万次请求，目标成功率99.9%，允许失败多少？','失败比例0.1%=0.001。','1000000×0.001=1000。','1000次，需明确统计窗口和哪些请求计入。'],['平均延迟100ms能否证明99%请求也小于100ms？','不能，分布可能长尾，需测相应分位数与样本质量。'],['重试越多系统一定越可靠？',['一定','不一定，可能形成重试风暴','无需退避','只看CPU'],1,'故障时额外请求可能进一步耗尽资源。'],['交付可靠云服务设计','定义SLI/SLO、幂等、过载保护、恢复演练与成本权衡。'])],240);
D(66,'区块链怎样在不完全信任中维护状态，去中心化要付出什么成本？',['哈希、签名和网络基础','分布式故障与状态机'],[64,65,49],['ethereum','cs50'],[
L('账本、哈希与签名',['区块链把交易或状态变化按规则组织，并通过哈希链接帮助检测历史篡改。哈希并不单独阻止攻击者重写全部历史，共识和经济或权限机制才决定哪条历史被接受。数字签名证明某私钥持有者授权了对应消息，并不自动证明消息陈述的现实事实真实。','账户地址不是身份证，链上可见也不等于完全匿名。密钥丢失、被盗或授权错误会带来实际损失，课程仅在测试环境操作虚拟资产。区块链适合需要多方共享验证且难指定共同可信管理者的某些情境，普通数据库往往更便宜、更容易保护隐私与纠错。'],[['数字签名','使用私钥签署并由公钥验证消息授权与完整性的机制。'],['状态机','按规则将当前状态和输入映射到新状态的模型。']],['虚拟链上记录某批食品产地，能保证现实产地正确吗？','签名可确认谁提交了记录。','输入前现实调查仍可能出错或造假。','不能，链上完整性不等于链下真实性。'],['哈希链接为何不足以单独防止整链重写？','攻击者可重算后续哈希，需要共识与权重或权限机制决定可接受历史。'],['签名最直接证明什么？',['现实事件必真','相应私钥授权了消息','账户必实名','合约没有漏洞'],1,'身份、事实和程序安全需要其他证据。'],['画账本信任模型','说明参与者、状态规则、密钥和链外事实验证。']),
L('共识、最终性与激励',['共识使参与节点在故障或恶意行为存在时对状态达成一定一致，具体保证依赖网络、故障比例和协议。工作量证明与权益证明使用不同资源和激励约束，不能只按名字判断绝对安全。分叉与最终性涉及历史何时可被视为难以或不能按规则回滚，保证必须限定协议条件。','交易费用反映有限区块空间竞争与执行资源，吞吐、去中心化和安全之间存在多维设计权衡。链外扩展、汇总和桥接引入新的验证、可用性与托管假设。经济激励能改变攻击成本，却不是没有漏洞或无法串谋的数学证明；代币价格也不是技术质量指标。'],[['最终性','在明示协议假设下历史确认不可逆或回滚风险受限的性质。'],['共识假设','协议保证依赖的网络、故障和参与条件。']],['虚拟应用看到交易广播就发不可撤销商品，有何问题？','广播不等于入块。','入块也需理解最终性与分叉条件。','应按业务损失容忍度制定确认策略，而非只看发送成功。'],['提高单机硬件要求为何可能影响去中心化？','更多参与者无法承担验证成本，节点分布与权力集中可能变化。'],['共识安全保证是否脱离假设永远成立？',['是','否，网络与故障条件重要','只看品牌','价格高即安全'],1,'分布式协议性质总有明确模型条件。'],['比较两种共识威胁模型','列资源、故障、最终性和验证参与门槛。']),
L('智能合约与应用治理',['智能合约是在链上按规则执行的程序，不因名字而自动具有法律效力或智能判断能力。代码可能包含重入、权限、算术、预言机或升级风险，公开可读也不保证经过充分审查。程序执行不可轻易撤销，使规格、测试、审计与应急治理尤为重要。','去中心化应用仍可能依赖集中前端、RPC、预言机、管理员密钥或托管方，必须逐项画出信任边界。治理升级能修复问题，也引入权力与滥用风险；完全不可升级同样有代价。毕业项目应在测试链用虚拟价值演示状态不变量、权限和故障，不以投机收益宣传技术。'],[['预言机','将链外数据引入合约的机制及其信任来源。'],['状态不变量','所有合法执行后应持续成立的安全性质。']],['虚拟合约仅管理员可提款，管理员密钥泄露后是否仍因去中心化而安全？','提款权限由该密钥控制。','攻击者可按合约授权执行。','不安全，需评估多签、限额、监控和恢复等具体控制。'],['合约代码公开就等于已审计吗？','不等于，可见性不代表有人完成规格、测试与独立审查。'],['dApp完全无需信任任何外部组件吗？',['无需','通常仍有具体依赖需分析','只要有代币','前端不重要'],1,'链外入口与治理常构成重要信任点。'],['交付测试链合约项目','提交规格、不变量、权限测试、链外依赖和升级风险说明。'])],200);
D(67,'传感、通信与控制怎样构成可靠智能设备？',['电压、电流和基本电路','编程、网络与采样'],[56,64,65],['pi','sre'],[
L('传感、采样与误差',['传感器把物理量转成可读信号，精度、分辨率、重复性和量程是不同指标。高位数ADC不保证系统准确，噪声、校准、温漂和安装都会影响结果。测量前需明确对象、单位与参考标准，传感器显示一个数字并不意味着它直接等于真实值。','采样将连续变化转为离散序列，若信号含高频成分而采样不足，可能发生混叠。奈奎斯特条件在带限与理想重建等前提下要求采样率超过最高频率的两倍，实际仍需抗混叠滤波与裕量。设备实验遵守电气额定与低压安全，不连接未经评估的市电或危险执行器。'],[['分辨率','系统能够区分的最小输出变化尺度。'],['混叠','采样不足使不同频率成分在离散数据中不可区分。']],['虚拟0–3.3V、12位ADC，理想码宽约多少？','共有2¹²=4096级。','3.3/4096≈0.000806V。','约0.806mV，但不等于实际精度。'],['最高10Hz的理想带限信号，采样率应怎样？','理论需高于20Hz，实际加滤波并选裕量，不能把20Hz边界当普遍保证。'],['ADC位数提高能自动消除温漂吗？',['能','不能','只看厂家','量程无关'],1,'量化分辨率与传感器系统误差不同。'],['建立传感校准记录','使用安全教学数据比较参考值、偏差、重复性和温度影响。']),
L('边缘计算、协议与功耗',['物联网包含设备、网关、网络、平台和应用，数据路径的每段都可能失败。边缘计算在靠近采集处处理，可减少延迟和传输，但增加现场软件、功耗与维护复杂性。选择集中或边缘应依据连接、隐私、实时与成本需求，不是越智能越好。','发布订阅协议将生产者和消费者解耦，但消息质量等级不等于端到端业务只发生一次。设备应带时间戳、序号或幂等标识，考虑离线缓冲和时钟漂移。低功耗设计要核算休眠、采样、计算和无线发送各状态占比，平均电流必须按时间加权。'],[['边缘计算','在靠近数据来源处进行部分处理与决策。'],['占空比','某工作状态在总时间中所占比例。']],['虚拟设备10%时间10mA、90%时间0.1mA，平均电流多少？','加权0.1×10+0.9×0.1。','结果1+0.09=1.09。','1.09mA，未计启动脉冲和电源损耗。'],['网络断开时直接丢数据是否总可接受？','不是，要按任务定义缓冲、过期、重传与安全降级，实时控制可能需本地继续。'],['协议确认收到是否等于业务处理成功且仅一次？',['等于','不等于','只看QoS名字','无需标识'],1,'传输与业务事务边界不同。'],['设计离线设备管道','模拟断网、重复与时钟漂移，记录恢复和数据完整性。']),
L('闭环控制与设备全寿命',['闭环控制用传感反馈比较目标与实际，再调整执行器。反馈可以减少扰动影响，但延迟、噪声和过大增益可能导致振荡或不稳定。PID的比例、积分、微分分别反映当前误差、累积误差和变化趋势，实际需滤波、限幅与积分饱和处理。','设备安全覆盖身份、密钥、固件验证、更新、物理访问和退役。部署后难维护的设备若没有安全更新，会长期积累漏洞；更新失败也可能使设备不可用，因此需签名、回滚与分阶段策略。毕业作品应包括失联与传感故障时的安全状态，不能只演示网络良好时的自动化。'],[['反馈控制','依据输出测量调整输入以接近目标。'],['安全降级','故障时转入风险可接受的受限功能状态。']],['虚拟温控器传感器断线却继续全功率加热，有何设计缺陷？','反馈输入已失效。','未定义断线检测和安全状态。','应停止或限制加热并告警，具体取决于安全分析。'],['控制增益越大是否总跟踪越好？','不一定，延迟和动态可导致超调、噪声放大与不稳定。'],['设备安全更新最需兼顾？',['只看下载速度','真实性、恢复与业务安全','只看界面','永不更新'],1,'错误或恶意更新和失败恢复都可能产生严重后果。'],['交付安全设备设计','含采样、功耗、反馈、断网、升级和退役的测试矩阵。'])],200);
D(68,'怎样构建可访问、响应迅速并兼容不同设备的网页体验？',['HTML、CSS与基本JavaScript','网络请求与浏览器基础'],[44,64,69],['mdn','wai'],[
L('语义结构与响应式布局',['HTML表达内容结构与语义，CSS控制表现，JavaScript添加交互。按钮用于动作、链接用于导航，语义正确能帮助键盘、屏幕阅读器和浏览器默认行为。用可点击div模拟按钮还要自行补键盘和状态，通常比直接使用原生元素更易出错。','响应式设计从内容和任务出发，使用弹性布局、相对尺寸、媒体查询和适当图片，让界面随视口而非某个手机型号调整。正文应有可读行宽、足够字号与对比，触摸目标与间距要适合手指。禁止横向溢出不能靠把所有内容裁掉，表格和代码要有明确可滚动容器。'],[['语义HTML','用与内容和行为含义匹配的原生元素组织页面。'],['响应式布局','依据可用空间和能力调整呈现与交互。']],['虚拟删除操作该用a还是button？','它改变状态而非导航到资源。','选button并提供明确名称和必要确认。','使用按钮语义，键盘默认可激活。'],['长代码使手机整页溢出应如何处理？','给代码区域max-width与局部横向滚动，保持页面主体宽度和可访问标签。'],['响应式只需把电脑页面缩小吗？',['只需','不够，应重排内容与交互','字号越小越好','所有设备固定宽'],1,'缩小可能使文字、触控和层级不可用。'],['制作跨屏阅读页','在窄屏和宽屏检查导航、正文、表格、代码与触控。']),
L('状态、异步与可访问交互',['网页状态包括数据、加载、空结果、错误和用户输入，不能只设计成功路径。异步请求可能乱序返回，旧搜索结果覆盖新输入就是竞态；可以取消旧请求或使用请求标识，只接受当前结果。失败时要给可恢复操作而不是让用户面对空白页面。','可访问表单需要可关联标签、错误说明和明确焦点；模态框要管理焦点进入、限制背景交互并在关闭后恢复。动态更新可以用适当live区域通知，但整页频繁朗读会干扰。交互测试应包括键盘、缩放、减弱动效偏好及辅助技术，视觉看起来正常不是全部验收。'],[['竞态条件','结果受异步执行顺序影响而产生错误状态。'],['焦点管理','让键盘焦点随任务变化处于可理解、可操作的位置。']],['虚拟先搜A后搜B，A慢返回却覆盖B，怎样避免？','给每次请求递增标识。','渲染前确认标识仍是最新，或取消旧请求。','只展示与当前查询匹配的结果，同时处理错误。'],['关闭模态框后焦点应去哪？','通常恢复到打开它的控件或合理后续位置，避免掉到页面开头或隐藏内容。'],['加载失败显示空白是否合格？',['合格','不合格，应说明错误与恢复方法','用户会刷新即可','只看网络'],1,'可靠体验包括异常和可恢复路径。'],['实现可访问搜索与对话框','测试乱序、失败、空结果、键盘和关闭恢复焦点。']),
L('性能、安全与体验评估',['性能需用用户可感知指标与真实任务衡量，网络慢、设备弱和长页面都可能暴露问题。按需加载、合理图片、减少阻塞和缓存可改善体验，但要处理版本更新与失败恢复。缓存过期或引用错版本会让新页面读取旧数据，因此资源版本与数据契约应一致。','前端安全不能信任来自URL、存储或外部内容的字符串，插入页面需安全编码或可靠净化，授权必须由服务端执行。可用性研究结合任务完成、错误和定性反馈，A/B实验关注因果效果。毕业作品应有跨视口、键盘、性能和异常测试，明确静态站点与服务器功能的边界。'],[['按需加载','在需要时加载资源以降低初始传输和计算。'],['内容注入风险','不可信数据被解释为可执行页面内容的风险。']],['虚拟学习站点有300份课程，首页是否必须全下载？','首页先加载目录和当前所需信息。','进入课程时按需加载并缓存，处理失败。','通常无需一次下载全部正文，但搜索策略需另行设计。'],['把URL参数直接赋给innerHTML有何风险？','可能形成脚本或标记注入，应使用文本节点或受控净化并限制URL协议。'],['性能验收应只在开发者电脑进行吗？',['只需','不应，还需慢网与较弱设备或模拟','只看截图','文件少就快'],1,'用户环境差异会改变加载与交互成本。'],['交付可维护响应式网站','提交语义、状态、跨屏、键盘、安全与性能的验收记录。'])],240);
D(69,'软件怎样从需求走到可演进系统，架构和测试如何降低风险？',['编程、数据结构与Git','网络和数据库基础'],[61,64,65],['cs50','sre'],[
L('需求、模块与接口',['软件工程处理的不只是写代码，而是需求理解、协作、质量和长期变化。需求应描述使用场景、可观察结果与约束，验收标准使团队能判断何时完成。把含糊需要直接转成实现会把误解固化，原型和示例有助于暴露歧义，但不能代替真实业务确认。','模块通过隐藏内部决策降低变更传播，接口说明输入、输出、错误和不变量。高内聚让相关职责聚在一起，低耦合减少不必要依赖，二者不是按文件数机械衡量。抽象应基于稳定概念和实际变化，不要为未来所有可能性过度设计，复杂度本身也有维护成本。'],[['信息隐藏','通过模块边界封装可能变化的内部设计。'],['接口契约','输入、输出、错误与必须保持性质的约定。']],['虚拟三个页面各复制价格计算，修改规则时有什么风险？','逻辑重复可能只改部分。','统一稳定的计算接口并保留调用场景测试。','减少规则漂移，但不应把无关规则硬合并。'],['函数不说明失败返回值会导致什么？','调用者可能误判错误为正常数据，需明确异常、错误值或结果类型契约。'],['模块划分最好只按代码行数吗？',['最好','不应，应依据职责和变化边界','文件越多越好','一个文件最省事'],1,'模块的价值在隔离变化和理解成本。'],['编写小系统规格','列用户场景、验收示例、模块职责和接口错误。']),
L('测试分层与持续集成',['单元测试快速检查局部逻辑，集成测试检查组件边界，端到端测试验证关键用户路径；三者覆盖不同风险。测试通过不能证明没有缺陷，尤其当断言只镜像实现时，错误可能被一起复制。应从需求、边界、反例和已知故障设计测试，而不是为覆盖率数字堆用例。','持续集成在小批变更时运行检查，版本控制保留可审查差异与回退路径。可复现构建需锁定依赖和环境，数据迁移要考虑旧新版本兼容。自动化不能替代探索性与可用性检查，但可以降低重复验证成本，让开发者更早发现接口和数据契约破坏。'],[['测试预言','判断程序输出是否正确的依据。'],['持续集成','频繁集成变更并自动执行构建与质量检查。']],['虚拟价格函数实现和测试都复制同一错误公式，会怎样？','测试预期与实现共享错误。','即使全部通过，也未验证需求。','应使用独立手算、边界和业务样例作为预言。'],['端到端测试慢且易波动，应全部替代单元测试吗？','不应，按风险分层，关键路径端到端验证，局部逻辑用快速精确测试。'],['100%代码覆盖率意味着无缺陷吗？',['意味着','不意味着，覆盖不等于断言有效','无需需求','无需边界'],1,'执行过代码并不保证检查了正确行为。'],['建立持续交付检查','为虚拟服务配置独立预言、契约测试、构建和回退演练。']),
L('架构决策与演进治理',['架构是对系统质量和演进影响重大的结构与决策。单体和微服务不是成熟度排名，分布式拆分会增加网络故障、数据一致性、部署与观测成本；业务边界和团队能力不足时，模块化单体可能更适合。选择应围绕性能、可靠性、安全、可维护和成本进行权衡。','架构决策记录说明背景、选项、取舍、后果和复审条件，避免人员变化后只剩无法解释的限制。技术债是为短期收益接受的未来成本，应区分有意识取舍与无意缺陷。优秀毕业项目应展示需求到设计、实现、验证和运维的追溯，包含故障模式、数据恢复和演进计划。'],[['架构决策记录','保留重要选择的背景、备选、理由与后果。'],['技术债','当前设计取舍导致的未来变更或维护成本。']],['虚拟两人团队低流量应用要拆20服务，主要代价是什么？','增加网络、部署、版本和观测复杂性。','业务收益可能不足以覆盖运维成本。','应先依据边界和质量目标比较模块化单体，而非追随潮流。'],['为何要记录被放弃方案？','使未来条件变化时可复审，理解当前约束并避免重复争论。'],['微服务必然比单体可维护吗？',['必然','不必然，取决于边界与运维能力','服务数越多越好','数据一致性无关'],1,'架构收益伴随协调和故障成本。'],['交付软件工程毕业项目','提交规格、架构记录、代码、测试、部署、监控和恢复证据。'])],260);
D(70,'量子信息怎样改变计算，哪些加速主张有严格条件？',['复数、向量和矩阵','概率、算法与基础物理'],[55,61,51],['quantum','calculus'],[
L('量子位、振幅与测量',['量子位的纯态可写为α|0⟩+β|1⟩，复振幅满足|α|²+|β|²=1，按计算基测量得到相应概率。叠加不是能直接读出所有答案的普通并行列表，测量只给一个结果并改变状态描述。相位影响干涉，不能只用概率表完整表示纯态。','量子门在理想封闭演化中用酉变换表示，保持总概率。Hadamard门把基态变成特定叠加，再施加一次可恢复原态，说明相干演化与经典随机抛硬币不同。实际设备有噪声、退相干和读出误差，电路模拟结果不能自动代表硬件可靠执行。'],[['振幅','复数状态系数，其模平方给特定基测量概率。'],['酉变换','保持内积和总概率的理想量子演化。']],['状态(√3/2)|0⟩+(1/2)|1⟩，测得1概率多少？','对|1⟩振幅取模平方。','|(1/2)|²=1/4。','25%，总概率3/4+1/4=1。'],['振幅-1/√2与+1/√2测量概率是否不同？','单独该基概率相同，但相对相位可在后续干涉中造成差异。'],['叠加能否一次读出全部计算结果？',['能','不能，测量规则限制读取','量子位越少越能','只要截图即可'],1,'量子算法需设计干涉使有用答案概率上升。'],['模拟单量子位电路','计算并模拟H与相位门序列，比较振幅和测量频率。']),
L('纠缠、电路与查询加速',['多量子位联合态不能总分成各量子位独立状态的乘积，无法如此分解的纯态可表现纠缠。Bell态测量结果相关，但不允许用这种相关性超光速传递任意信息。经典相关与量子纠缠需用恰当实验和数学条件区分，不能把所有同步现象都叫纠缠。','量子算法通过可控演化与干涉提取结构，Grover搜索在标准无结构查询模型下有平方级查询加速，而不是对所有数据库任务无条件瞬间搜索。装载数据、实现预言机、纠错与读出可能很昂贵。比较经典与量子方案要明确输入模型、资源口径和成功概率。'],[['纠缠','联合量子态不能按所选子系统分解为独立状态的性质。'],['查询复杂度','算法调用给定信息黑箱的次数，不等于全部运行成本。']],['Bell态(|00⟩+|11⟩)/√2测量两位，可能结果与概率？','|00⟩和|11⟩振幅均1/√2。','各自模平方1/2。','00与11各50%，单次结果不能由一方自由指定。'],['N=10000的理想无结构搜索，平方级查询尺度约多少？','O(√N)即约100的尺度，常数和预言机实现另计。'],['Grover加速是否说明任何搜索都总更快？',['是','否，模型与全部资源成本重要','无需数据访问','所有问题指数加速'],1,'查询优势不能省略输入和硬件成本。'],['比较经典与量子搜索模型','列预言机、输入、查询、门数和成功概率，避免仅比标题。']),
L('噪声、纠错与优势证据',['量子噪声可改变相位、振幅或读出结果，电路越深越易累积误差。量子纠错将逻辑信息编码到多个物理量子位，并通过综合征提取错误信息而尽量不直接测量逻辑态；不能把纠错理解为复制任意未知量子态，因为不可克隆定理限制这种复制。','展示量子优势需要与适当经典基线在明确任务、误差和资源下比较。物理量子位数不是独立充分指标，还需门保真度、连接、运行深度和纠错开销。近期应用主张应区分理论、模拟与硬件证据，毕业作品要给可复核电路、噪声模型、经典对照和不确定性，不宣称普遍取代经典计算。'],[['逻辑量子位','通过编码与纠错保护的计算信息单位。'],['综合征','用于识别可纠正错误而不直接读取逻辑信息的测量结果。']],['虚拟100个门各独立99%成功，全部成功概率近似多少？','简化独立模型相乘。','0.99¹⁰⁰≈0.366。','约36.6%，说明积累效应；真实错误并非都独立。'],['两台量子机一台位数多就必然更强吗？','不能，门误差、连接、深度、纠错和任务实现都影响可用能力。'],['量子纠错是否靠任意复制未知量子态？',['靠','不靠，不可克隆限制复制','只需经典备份','无需测量'],1,'编码和综合征提取不同于复制未知态。'],['完成量子算法证据报告','模拟含噪电路，比较经典基线、误差与资源，明确优势适用域。'])],220);
const detail={
36:['收益的比较还必须统一持有期，年化数值只是把既定期间结果转换成可比较尺度，不会把短样本变成长期可靠证据。','资产数量增加也可能只是买入相同风险因子的不同包装，因此要检查底层持仓和共同暴露，而非只统计产品名称。','选择基准应在观察结果前确定，否则事后挑选较弱基准会夸大绩效；收益归因也要区分市场暴露和主动决策。'],
37:['同一个人在不同时间的选择变化也可能来自信息更新，而不是心理偏差，研究应记录当时可知的信息与真实约束。','长期目标由谁定义同样重要：研究者不能把自己偏好的储蓄或健康目标强加给参与者，再把不同选择直接称作错误。','若干预改变被试是否回答调查，观测到的满意度可能混入失访选择；应比较失访率并进行敏感性分析而非只删缺失。'],
38:['工资数据还要说明是税前还是税后、小时还是月度，以及是否包含奖金福利，否则组间比较可能只是统计口径差异。','教育效果可能因专业、学校、经济周期和学生背景而不同，平均回报不应被解释为所有个体都能获得相同收益。','政策发生时间不同的地区可能具有不同效应，简单合并估计会产生难解释权重，应根据研究设计选合适估计方法。'],
39:['家庭规模调整涉及共享住房等规模经济，不应机械把总收入除人数作为唯一福利衡量，需说明等价尺度及其敏感性。','风险保障可以使家庭敢于投入回报较高但波动大的活动，收入增长可能来自风险约束放松，而不只是资金数量增加。','财政预算有限时应同时比较机会成本，即把同一资金投入其他政策可能获得什么结果，不能只看项目内部是否有改善。'],
40:['同侧网络效应也可能为负，例如司机增加会加剧司机间竞争，因此需要把平台两侧的收益与拥挤分别测量和解释。','评估市场力量还可观察提价后用户转移和服务质量变化，但价格试验必须考虑伦理、合同和长期反应，不能简单套公式。','用户同意条款不自动意味着其充分理解数据用途，治理还需清晰说明、合理默认与可操作的撤回和删除机制。'],
41:['愿付价格本身也可能受信息不足或误导影响，因此顾客支付不自动证明交易对其有益，需要关注承诺与实际交付。','固定成本在短期可不随销量变化，但长期可能扩容或缩减；保本模型应注明分析期限，不能把所有成本永久固定。','供应商、员工和顾客之间的信任可降低协调成本，但也会因违约而快速受损，关系资本需要具体行为和历史记录支持。'],
42:['同一企业可有多种收入来源和顾客群体，画布若过度压缩会掩盖冲突，可以分别绘制后再说明共享资源和相互依赖。','实验的成功阈值应联系商业可行性，例如转化率是否足以覆盖获客成本，而不是只要求相对于零有统计差异。','若模式依赖少数伙伴，需记录对方的替代选择、议价能力与合同期限，增长可能反而使这种依赖成为关键风险。'],
43:['品牌承诺必须与售后、物流和产品体验一致，传播创造的期望越高，交付不足时失望也可能越大，不能只优化广告文案。','渠道之间可能互相影响，看到广告后通过自然搜索购买仍可能有广告贡献，因此单触点归因与总体增量要分开。','评估长期品牌效果可使用固定口径追踪与分地区实验，但竞争和媒体环境变化仍需记录，避免把全部变化都归功于活动。'],
44:['研究时应取得参与者知情同意并减少敏感记录，真实行为证据并不意味着可以秘密收集所有数据，隐私也是产品约束。','优先级中信心较低的高价值项目可先安排小实验，而不是直接排除或立即重投入，学习本身也有降低风险的价值。','埋点定义变化会制造虚假的趋势断点，例如活跃口径从访问改为完成任务，应记录版本并避免直接拼接比较。'],
45:['创业机会还依赖时机，基础设施、支付习惯和监管条件变化可能让旧想法变得可行，需要具体证据而非只说风口到了。','跑道估计应包括必须支付但尚未出账的义务和最低现金储备，账面余额不等于全部可自由用于试验的资金。','留存率要按用户进入时间和目标行为定义，少数重度用户的高使用频率不能替代对整个目标群体重复价值的检验。'],
46:['协调机制要适应任务互依程度，独立任务可分散决策，高互依任务则需要共同计划和接口检查，会议数量不是协作质量。','反馈接受者应有补充事实和提出不同解释的机会，单向宣布评价会遗漏情境并降低信任，必要时应核实第三方记录。','绩效制度应检查对不同岗位的测量公平，易量化岗位与协作支持岗位不宜直接按同一产出数字比较或分配奖励。'],
47:['瓶颈可能随产品组合和班次变化而转移，所以应周期性重测负荷，而不是把某台设备永久标为系统唯一约束。','批量处理可以降低换型成本，却通常增加等待与在制品，因此批量大小应与交付期限和需求波动一起权衡。','特殊原因信号值得调查但不是自动证明某个人犯错，应结合时间、设备和材料变更追踪机制，再决定是否调整过程。'],
48:['供应商与买方议价力还取决于集中度、替代和转换成本，不能只凭公司规模判断，需回到具体交易与约束。','模仿困难可能来自长期共同学习和难以分解的活动关系，但也可能只是观察信息不足，应谨慎区分证据与推测。','战略反馈周期应匹配机制发生时间，过快更改长期投入会妨碍学习，过慢又可能错过风险信号，需事先设复审条件。'],
49:['融资合同会影响坏情景下的控制与偿付，不能只比较好情景下创始人保留多少股份，应进行现金流和治理压力测试。','期权池若在投前扩大会由原股东承担不同程度稀释，谈判必须同时给股份数量和完全稀释口径，避免百分比错觉。','投资人需要了解后续融资和优先权叠加影响，单轮退出算例只是教学简化，多轮资本结构应按条款逐层分配并核查。'],
50:['后果计算的边界必须包含可预见的间接影响，但也应承认无法精确货币化的权利和尊严，不能用伪精确掩盖价值选择。','保密调查需兼顾被举报者的正当程序，未经核实的指控不应直接成为处罚依据，公平处理也是制度可信的重要部分。','披露遗漏可能比个别数字错误更重要，因此审计要先问哪些重大影响未被覆盖，再核对已经公布的指标和措辞。'],
51:['选择系统后还应检查内外力边界，内部力可改变部件运动而不改变封闭系统总动量，局部受力与整体守恒可以并存。','阻尼既消耗振动能量也能抑制共振风险，工程中往往主动设计阻尼，因此并非所有能量耗散都应被视为无用损失。','不确定性传播应考虑各测量量之间的相关，简单把误差全部相加或平方相加都需要对应假设，不能机械套一种规则。'],
52:['反应方程式还要注明物态和条件，气体体积比例只在适当温压近似下才与摩尔比例对应，不能把不同状态直接比较。','活度系数偏离一时浓度近似会变差，尤其高离子强度溶液；研究者应说明模型适用浓度范围并检查误差是否重要。','实验级数改变可能提示机理或控制步骤变化，但仍需排除传热传质限制，观察到速率变化不能立刻认定分子机理。'],
53:['细胞内分隔使不同反应能在不同环境中进行，膜结构与运输需要能量或梯度，功能解释必须同时考虑空间与时间。','遗传率是特定群体和环境下变异来源的统计量，环境改变会改变它，因此高遗传率不能推出教育或治疗完全无效。','独立重复应尽可能重新采样或独立完成关键步骤，仅重复读取同一试管不能代表生物学重复，也不能增加独立样本数。'],
54:['板块运动与风化还连接地质时间尺度的碳循环，短期生态调查不足以直接观察全部过程，需结合不同尺度的证据。','物种间作用可能随环境由竞争转为促进，关系图应注明条件，不能把某一时期测出的效应当作永久固定生态规律。','社区知识可帮助发现长期变化与管理副作用，但应与可追溯监测共同使用，不能因其非仪器来源而一概排除或全盘接受。'],
55:['使用反证法时应明确所处逻辑体系和命题否定，否定所有对象成立是存在至少一个反例，不是所有对象都不成立。','定积分上下限交换会改变符号，物理总路程则需积分速度绝对值，因此有符号位移和走过距离不能混为同一量。','矩阵计算要检查维度、秩与数值条件，理论有唯一解也可能对微小输入误差很敏感，算法输出多位小数不保证准确。'],
56:['需求还应标注来源和优先级，利益相关者冲突由有权决策者处理，不能让工程师在未说明的情况下偷偷决定价值取舍。','可靠度通常对应给定时间内无故障概率，可用性则涉及故障后的修复速度，两者相关但不同，维护设计会改变后者。','测试未覆盖的工况应明确写成未验证范围，不应把在室温通过的结论自动推广到高温、震动或长期老化环境。'],
57:['材料性能数据还需注明测试方向与速率，复合材料和加工金属可能各向异性，同一试样在不同方向会有不同表现。','相比例与质量比例或摩尔比例必须按相图和题目定义统一，若端点成分使用不同单位，直接代杠杆公式会得到错误结果。','性能评估需比较相同功能和测试条件，纳米样品与普通样品若厚度、纯度或工艺不同，提升未必由尺寸本身造成。'],
58:['效率比较应区分热值口径与系统边界，热泵的性能系数可大于一，因为它搬运环境热量而不是违反能量守恒。','电力负荷的峰值与能量总量不同，全年发电足够仍可能在某些小时缺电，因此可靠性分析需要时间序列而非仅年平均。','若未来电网逐步变清洁，同一设备不同年份用电排放会变化，生命周期估计应给出情景而非把当前排放因子永久固定。'],
59:['半衰期模型还取决于消除机制和浓度范围，某些过程会非线性或多相变化，因此教学指数曲线不能直接用来安排用药。','盲法可能因明显副作用被破坏，应检查分配隐藏、终点测量和失访原因，随机分组本身不能修复所有执行偏差。','筛查还可能发现不会造成症状的异常，过度诊断与假阳性不同，评估必须比较真实健康获益和后续检查治疗负担。'],
60:['温度异常相对某一基准期计算，不同基准会改变图上零点，但只要口径一致，不会凭空改变同一序列的长期变化趋势。','短寿命污染物和二氧化碳的寿命与效应不同，统一指标虽便于政策比较，也需说明时间尺度和转换假设，不能混同机制。','政策收入如何返还会改变不同收入群体负担，同样碳价可能对应不同分配结果，应把财政用途纳入政策整体评价。'],
61:['变量名不是物理内存地址的普适同义词，不同语言的值、引用和所有权模型不同，理解语义应查该语言规范与运行模型。','算法比较还要考虑缓存局部性与内存分配，渐近更优的方案在小输入上未必更快，但经验测试也不能替代规模分析。','动态规划的状态必须保留未来决策所需信息，状态过少会丢失最优性，过多则增加复杂度，设计应由问题结构推导。'],
62:['标签可能来自历史决策并包含测量偏差，模型学到的高准确关系可能复制旧制度问题，因此需先审查目标定义与标注。','超参数搜索也会消耗验证信息，尝试次数多时容易过拟合验证集，最终测试应保留到方案确定后并如实报告搜索过程。','训练和部署的风险随用途而变，同一模型用于娱乐与医疗需不同验证和责任，不能凭一个通用排行榜分数决定可用性。'],
63:['数据最小化要求只保留研究目的必要信息，去掉姓名并不保证匿名，位置、时间与其他字段组合仍可能重新识别个人。','置信区间和显著性都依赖模型与采样假设，若存在强聚类或时间相关却按独立样本计算，表面精确可能严重高估。','版本化不仅包括代码，也包括数据快照与口径，外部接口变化可能令相同代码得到不同结果，应记录取数时间与校验。'],
64:['账户恢复流程可能绕过强认证，因此需把重置邮箱、客服核验和备用凭据一起纳入威胁模型，安全取决于完整路径。','输入验证与输出编码应分层使用，合法业务文本也可能含尖括号或引号，不能通过随意删除字符代替上下文安全处理。','事故复盘应关注系统条件和改进责任，单纯责罚最后操作的人可能压低报告意愿，使相同风险继续隐藏并再次出现。'],
65:['云资源计费粒度与区域、网络流向可能不同，估算成本应记录请求量和数据出口，而不只是比较主机标价或免费额度。','一致性保证还需说明读写的对象与事务范围，单条记录强一致不自动提供跨多个服务的原子业务事务，接口必须明确。','错误预算需要与发布政策连接，例如预算耗尽时优先修复可靠性，但应允许有理由的例外并记录负责人与恢复计划。'],
66:['私钥控制权与法律所有权可能不一致，托管、继承与纠纷处理仍有现实制度需求，不能把密码学授权当成全部权利判断。','比较共识资源时要统一安全目标与攻击假设，不能只用每秒交易数宣称全面优越，节点验证和状态增长也有长期成本。','合约依赖的价格数据可能被操纵或延迟，必须说明来源、更新、异常处理和失效模式，预言机是系统安全的一部分。'],
67:['校准应覆盖使用范围而非只校准一个点，并记录参考仪器的不确定性；超出已校准范围的读数需要额外验证。','无线传输的峰值电流可能超过电池或稳压器能力，即使平均功耗低也会重启，因此电源设计还需检查瞬态与储能。','执行器的物理后果使设备安全超出软件范围，机械限位、独立保护和人工停止可能必需，应由具体风险分析决定。'],
68:['页面缩放至较大比例时仍应保留内容与操作，布局不能把重要按钮挤到屏外，字号和行高也应允许用户设置覆盖。','错误提示应说明如何修正并与对应字段关联，仅用红色标记会让部分用户无法理解，提交后应定位到合理错误位置。','真实体验还受内容质量影响，快速加载一个没有答案的页面并不满足学习任务，性能应与任务完成和阅读理解一起评价。'],
69:['接口版本变更应考虑旧客户端和数据格式，新增字段通常比改变既有字段含义更易兼容，但仍需根据契约实际测试。','不稳定测试会削弱团队信任，修复应查时钟、并发、外部依赖和数据隔离，不能长期忽略失败或反复重跑直到变绿。','技术债管理应记录影响、偿还成本和触发条件，所有重构都要关联现实质量或变更需求，不能把个人审美当唯一理由。'],
70:['物理全局相位对单独状态的测量概率无影响，相对相位却能影响干涉，这一区别解释了为什么只列概率不足以描述演化。','纠缠相关不能由一方选择测量结果来编码任意消息，接收者还需经典通信比较记录，因此不会提供超光速信道。','硬件演示若只挑选最好的一次结果会高估表现，应报告重复运行、错误条与后处理，说明是否存在选择性保留样本。']};
for(const p of packs) p.stages.forEach((s,i)=>s.lesson.push(detail[p.domainId][i]));

